  if(pid==="D"&&i===j){const a=opts.brideDesignation,b=opts.groomDesignation;
    if(a&&b){score=a!==b?4:3;note=a!==b?"Same Yoni with complementary male/female designations: 4.":"Same Yoni with identical designations: 3."}
    else note="Designation not available (for example Abhijit): same Yoni scored 4."}
  const enemy=isEnemy(i,j),cat=categoryOf(pid,i,j,m),rev=m[j-1][i-1];
  return {brideYoni:i,groomYoni:j,relationshipCategory:cat,score,enemyFlag:enemy,friendshipFlag:cat==="Friendly",
    directionalScore:{forward:m[i-1][j-1],reverse:rev,asymmetric:m[i-1][j-1]!==rev},scoringProfileId:pid,note};
