  const pd=calculatePanchadhaMaitri("Sun","Mercury",{Sun:1,Mercury:3},{});ok("Panchadha is calculated in both directions and can differ (Sun→Mercury Mitra, Mercury→Sun Adhimitra)",pd.panchadhaAB.key==="Mitra"&&pd.panchadhaBA.key==="Adhimitra","");
  const sc=[["Same lord",1,8,5],["Mutual friends",1,5,5],["Friend + Neutral",5,6,4],["Neutral + Neutral",1,2,3],["Friend + Enemy",4,6,1],["Neutral + Enemy",1,10,0.5],["Mutual enemies",5,10,0]];
  sc.forEach(s=>ok(`Koota: ${s[0]} = ${s[3]}`,calculateGrahaMaitriKoota(s[1],s[2]).score===s[3],""));
  ok("The 7 × 7 score matrix equals the specified matrix",JSON.stringify(scoreMatrix())===JSON.stringify(EXPECT_SCORE),"");
  const verify=[["Sun","Moon",5],["Sun","Mercury",4],["Moon","Mercury",1],["Mars","Venus",3],["Mercury","Saturn",4],["Jupiter","Venus",0.5],["Sun","Saturn",0],["Saturn","Venus",5]];
  verify.forEach(v=>ok(`7×7 check: ${v[0]} and ${v[1]} = ${v[2]}`,scoreMatrix()[PLANETS.indexOf(v[0])][PLANETS.indexOf(v[1])]===v[2],""));
  const R=rashiMatrix();ok("The 12 × 12 matrix has exactly 144 cells",R.length===12&&R.every(r=>r.length===12),R.flat().length);
  [[1,8,5],[2,7,5],[3,6,5],[9,12,5],[10,11,5],[4,6,1],[5,10,0],[2,11,5],[1,12,5]].forEach(c=>ok(`12×12 check: ${SIGNS[c[0]-1].en} and ${SIGNS[c[1]-1].en} = ${c[2]}`,R[c[0]-1][c[1]-1].score===c[2],""));
