  const before=JSON.stringify(rashiMatrix());const keep=JSON.stringify(NATURAL.custom.table);
  const saved=JSON.parse(JSON.stringify(NATURAL.custom.table));NATURAL.custom.table.Sun.Moon="E";
  ok("Editing the custom natural table does not change the standard profile",JSON.stringify(rashiMatrix())===before&&getNaturalRelationship("Sun","Moon","std7").aRegardsB==="F","");NATURAL.custom.table=saved;
  const k1=calculateGrahaMaitriKoota(4,6).score;TEMPORARY.C.friends=[2];const k2=calculateGrahaMaitriKoota(4,6).score;TEMPORARY.C.friends=[2,3,4,10,11,12];
  ok("Changing the temporary / Panchadha rule does not change the Koota score",k1===k2,"");
  const t0=JSON.stringify(naturalMatrix());const sv=JSON.parse(JSON.stringify(SCORING.custom.table));SCORING.custom.table.FF=1;
  ok("Changing the scoring table does not change the natural friendship data",JSON.stringify(naturalMatrix())===t0&&calculateGrahaMaitriKoota(1,5,"custom").score===1&&calculateGrahaMaitriKoota(1,5,"A").score===5,"");Object.assign(SCORING.custom.table,sv);
