  let thrown=0;[[0,1],[13,1],[1.5,1],["a",1]].forEach(p=>{try{calculateGrahaMaitriKoota(p[0],p[1])}catch(e){thrown++}});ok("Invalid Rashi input is rejected",thrown===4,thrown+" of 4");
  if(typeof external==="function"){let same=true,bad="";for(let b=1;b<=12;b++)for(let g=1;g<=12;g++){const s=external(b,g);if(s!==calculateGrahaMaitriKoota(b,g).score){same=false;bad=`${b},${g}`}}ok("The new engine equals the existing Ashtakoota engine (lab) for all 144 sign pairs",same,bad)}
