/* ===== gana.js ===== */
/* Gana Koota engine (Day 7): pure calculation, independent of the user interface.
   Layers (never mixed):  1 allocation (Nakshatra -> Gana)  2 relationship (bride Gana x groom Gana)  3 score (profile matrix)
   4 Dosha flags (low score / traditional Rakshasa mix / research warning)  5 exception processing  6 interpretation.
   Changing the scoring profile never changes the allocation; exceptions never change the raw score.
   Matrices are read as ROW = BRIDE, COLUMN = GROOM. Data comes from tradition-A.json through LabUI.getData(). */
(function(){
"use strict";
const N=27;
const GANAS=[
 {id:0,name:"Deva",hi:"देव",gu:"દેવ",meaning:"divine",symbol:"Gentle, generous, harmonious (traditional symbolic label, not a statement about a person)"},
 {id:1,name:"Manushya",hi:"मनुष्य",gu:"મનુષ્ય",meaning:"human",symbol:"Balanced, worldly, practical (traditional symbolic label, not a statement about a person)"},
 {id:2,name:"Rakshasa",hi:"राक्षस",gu:"રાક્ષસ",meaning:"demonic / fierce",symbol:"Forceful, assertive, intense (traditional symbolic label, not a statement about a person)"}];
const NAMES=["Ashwini","Bharani","Krittika","Rohini","Mrigashira","Ardra","Punarvasu","Pushya","Ashlesha","Magha","Purva Phalguni","Uttara Phalguni","Hasta","Chitra","Swati","Vishakha","Anuradha","Jyeshtha","Mula","Purva Ashadha","Uttara Ashadha","Shravana","Dhanishta","Shatabhisha","Purva Bhadrapada","Uttara Bhadrapada","Revati"];
const data=()=>{const d=window.LabUI&&LabUI.getData&&LabUI.getData();if(!d||!d.gana)throw new Error("Rule data is not loaded yet.");return d};
function check(i,what){if(!Number.isInteger(i)||i<1||i>N)throw new RangeError((what||"Nakshatra")+" must be an integer from 1 to 27, got "+i)}
const gid=name=>GANAS.findIndex(g=>g.name===name);
// ---- profiles: JSON profiles A, B, A0, C, D; user edits to C live in memory/localStorage (set by the widget), never in the JSON
const overrides={};
function listProfiles(){const p=data().gana.profiles;return Object.keys(p)}
function getProfile(id){
  const p=data().gana.profiles[id];if(!p)throw new RangeError("Unknown Gana profile "+id);
  const m=overrides[id]||p.matrix;return Object.assign({id},p,{matrix:m.map(r=>r.slice())});}
function validMatrix(m,max){return Array.isArray(m)&&m.length===3&&m.every(r=>Array.isArray(r)&&r.length===3&&r.every(v=>typeof v==="number"&&isFinite(v)&&v>=0&&v<=(max||6)))}
function setProfileMatrix(id,m){if(id!=="C")throw new Error("Only the user-defined Profile C may be edited");if(!validMatrix(m,6))throw new RangeError("Matrix must be 3 x 3 with values from 0 to 6");overrides[id]=m.map(r=>r.slice())}
function resetProfile(id){delete overrides[id]}
// ---- layer 1: allocation
function getGanaByNakshatra(i){check(i);const n=data().nakshatra[i-1],id=gid(n.gana);return {index:i,name:NAMES[i-1],ganaId:id,gana:GANAS[id].name,hi:GANAS[id].hi}}
function listByGana(){const o={Deva:[],Manushya:[],Rakshasa:[]};for(let i=1;i<=N;i++)o[getGanaByNakshatra(i).gana].push(i);return o}
// ---- layer 2: relationship
function getGanaRelationship(brideGana,groomGana){
  const b=typeof brideGana==="number"?brideGana:gid(brideGana),g=typeof groomGana==="number"?groomGana:gid(groomGana);
  if(b<0||b>2||g<0||g>2)throw new RangeError("Gana must be Deva, Manushya or Rakshasa");
  return {brideGana:GANAS[b].name,groomGana:GANAS[g].name,brideId:b,groomId:g,key:GANAS[b].name+" (bride) – "+GANAS[g].name+" (groom)",same:b===g,rakshasaMix:(b===2)!==(g===2),
    kind:b===g?"same Gana":(b===2||g===2)?"mixed, involving Rakshasa":"mixed, Deva and Manushya"}}
// ---- layer 3: score
function matrixScore(profile,b,g){return profile.matrix[b][g]}
function calculateGanaScore(brideIdx,groomIdx,profileId){
  check(brideIdx,"Bride Nakshatra");check(groomIdx,"Groom Nakshatra");
  const p=getProfile(profileId||data().gana.activeProfile||"A"),bg=getGanaByNakshatra(brideIdx),gg=getGanaByNakshatra(groomIdx);
  return {profile:p.id,bride:bg,groom:gg,row:bg.ganaId,col:gg.ganaId,score:matrixScore(p,bg.ganaId,gg.ganaId),max:p.maxScore||6}}
// ---- layer 4: Dosha flags (three separate things)
const DEFAULT_THRESHOLD=1;
function doshaFlags(rel,score,profile,threshold){
  const th=threshold===undefined?DEFAULT_THRESHOLD:threshold;
  const low=score<=th,trad=rel.rakshasaMix;
  const research=profile.status!=="verified"||profile.id!=="A";
  return {lowScore:low,traditional:trad,researchWarning:research,threshold:th,
    any:low||trad,note:low&&!trad?"Low score without a Rakshasa mix: shown as a score flag only":!low&&trad?"Rakshasa mix, but the profile gives a score above the threshold":low&&trad?"Low score and a Rakshasa mix":"No flag"}}
// ---- layer 5: exception processing (identification only; nothing is applied without a user-supplied sourced rule)
const EXCEPTION_CATEGORIES=[
 {id:"graha_maitri",label:"Friendly or identical Rashi lords (Graha Maitri favourable)",basis:"Mentioned in some manuals as a mitigating consideration"},
 {id:"bhakoot",label:"Favourable Bhakoot relationship between the Moon signs",basis:"Mentioned in some manuals"},
 {id:"nadi_or_other",label:"Strong results in other Kootas (for example Nadi)",basis:"Mentioned in some manuals; a good score elsewhere does not by itself cancel a Dosha"},
 {id:"same_nakshatra_pada",label:"Same Nakshatra with different Pada, or the same Rashi",basis:"Mentioned in some manuals; school-specific"},
 {id:"navamsha_chart",label:"Supportive Navamsha and complete-chart factors (Day 13 layer)",basis:"Separate analytical layer, not a Koota rule"}];
function identifyExceptions(rel,flags){
  if(!flags.any)return [];
  return EXCEPTION_CATEGORIES.map(c=>Object.assign({},c,{status:"identified, not applied",requires:"school, source and exact conditions"}))}
// userRules: [{id,school,source,applies:fn(ctx)->bool}] supplied by the user; returns a status only, the raw score is never touched
function applyExceptions(result,userRules){
  const out=result.exceptions.map(e=>Object.assign({},e));
  (userRules||[]).forEach(r=>{if(!r||!r.id||!r.school||!r.source||typeof r.applies!=="function")return;
    if(r.applies(result)){out.push({id:r.id,label:r.label||r.id,school:r.school,source:r.source,status:"applied under the named school",basis:"user-supplied"})}});
  return {exceptions:out,rawScore:result.score,scoreChanged:false}}
// ---- layer 6: full compatibility result
function calculateGanaCompatibility(brideIdx,groomIdx,profileId,opts){
  opts=opts||{};
  const s=calculateGanaScore(brideIdx,groomIdx,profileId),p=getProfile(s.profile),rel=getGanaRelationship(s.row,s.col);
  const flags=doshaFlags(rel,s.score,p,opts.threshold),rev=getProfile(s.profile).matrix[s.col][s.row];
  const res={profile:p.id,profileName:p.name,profileStatus:p.status,bride:s.bride,groom:s.groom,relationship:rel,score:s.score,max:s.max,flags,
    reverseScore:rev,asymmetric:rev!==s.score,exceptions:identifyExceptions(rel,flags)};
  res.rawScoreUnchangedByExceptions=true;
  res.caution="Gana Koota is one component of traditional compatibility analysis. It is a symbolic temperament factor, and it should not independently determine marriage suitability or describe the real personalities of the people concerned.";
  return res}
// ---- generators
function generate3x3(profileId){const p=getProfile(profileId||"A");return GANAS.map((b,i)=>GANAS.map((g,j)=>({bride:b.name,groom:g.name,score:p.matrix[i][j],relationship:getGanaRelationship(i,j)})))}
function generateMatrix(profileId){const p=getProfile(profileId||"A"),m=[];for(let r=1;r<=N;r++){const row=[],bg=getGanaByNakshatra(r);for(let c=1;c<=N;c++){const gg=getGanaByNakshatra(c);row.push({bride:r,groom:c,brideGana:bg.gana,groomGana:gg.gana,score:p.matrix[bg.ganaId][gg.ganaId]})}m.push(row)}return m}
// reverse view: the same two Nakshatras with the roles swapped
function reverseView(brideIdx,groomIdx,profileId){const a=calculateGanaScore(brideIdx,groomIdx,profileId),b=calculateGanaScore(groomIdx,brideIdx,profileId);return {asEntered:a,swapped:b,differ:a.score!==b.score}}
function compareProfiles(brideIdx,groomIdx,ids){return (ids||listProfiles()).map(id=>{const s=calculateGanaScore(brideIdx,groomIdx,id);return {profile:id,score:s.score,max:s.max}})}
function transpose(m){return m[0].map((_,j)=>m.map(r=>r[j]))}
function differenceReport(idA,idB){
  const a=getProfile(idA).matrix,b=getProfile(idB).matrix,cells=[];
  for(let i=0;i<3;i++)for(let j=0;j<3;j++)if(a[i][j]!==b[i][j])cells.push({bride:GANAS[i].name,groom:GANAS[j].name,a:a[i][j],b:b[i][j]});
  const t=transpose(b),isT=JSON.stringify(t)===JSON.stringify(a);
  return {a:idA,b:idB,differingCells:cells,ordered27x27Affected:cells.length*81,identical:cells.length===0,aIsTransposeOfB:isT,totalA:a.flat().reduce((x,y)=>x+y,0),totalB:b.flat().reduce((x,y)=>x+y,0)}}
function asymmetryReport(profileId){const m=getProfile(profileId).matrix,out=[];for(let i=0;i<3;i++)for(let j=i+1;j<3;j++)if(m[i][j]!==m[j][i])out.push({pair:GANAS[i].name+" / "+GANAS[j].name,brideFirst:m[i][j],groomFirst:m[j][i]});return {symmetric:out.length===0,pairs:out}}
function distribution(profileId){const m=getProfile(profileId).matrix,d={};for(let i=0;i<3;i++)for(let j=0;j<3;j++){d[m[i][j]]=(d[m[i][j]]||0)+81}return d}
function toCsv(profileId){const M=generateMatrix(profileId);let s="Bride\\Groom,"+NAMES.map(n=>'"'+n+'"').join(",")+"\n";M.forEach((r,i)=>{s+='"'+NAMES[i]+'",'+r.map(c=>c.score).join(",")+"\n"});return s}

function runTests(){
  const out=[],ok=(n,c,d)=>out.push({name:n,pass:!!c,detail:d===undefined?"":String(d)});
  const L=listByGana(),D=data();
  ok("Allocation: 9 Nakshatras in each Gana",L.Deva.length===9&&L.Manushya.length===9&&L.Rakshasa.length===9,[L.Deva.length,L.Manushya.length,L.Rakshasa.length].join("/"));
  ok("Allocation covers all 27 Nakshatras exactly once",[...L.Deva,...L.Manushya,...L.Rakshasa].sort((a,b)=>a-b).join()===[...Array(27).keys()].map(x=>x+1).join(),"");
  const exp={Deva:["Ashwini","Mrigashira","Punarvasu","Pushya","Hasta","Swati","Anuradha","Shravana","Revati"],Manushya:["Bharani","Rohini","Ardra","Purva Phalguni","Uttara Phalguni","Purva Ashadha","Uttara Ashadha","Purva Bhadrapada","Uttara Bhadrapada"],Rakshasa:["Krittika","Ashlesha","Magha","Chitra","Vishakha","Jyeshtha","Mula","Dhanishta","Shatabhisha"]};
  Object.keys(exp).forEach(k=>ok("Allocation matches the course list: "+k,JSON.stringify(L[k].map(i=>NAMES[i-1]))===JSON.stringify(exp[k]),""));
  ok("Engine names match the data file order",D.nakshatra.every((n,i)=>n.name===NAMES[i]),"");
  const A=getProfile("A").matrix,B=getProfile("B").matrix,A0=getProfile("A0").matrix;
  ok("Profile A matrix (bride row, groom column) = 6,5,1 / 6,6,0 / 0,0,6",JSON.stringify(A)===JSON.stringify([[6,5,1],[6,6,0],[0,0,6]]),JSON.stringify(A));
  ok("Profile B matrix = 6,6,0 / 5,6,0 / 1,0,6",JSON.stringify(B)===JSON.stringify([[6,6,0],[5,6,0],[1,0,6]]),JSON.stringify(B));
  ok("Profile A0 (earlier draft) = 6,6,1 / 5,6,0 / 0,0,6",JSON.stringify(A0)===JSON.stringify([[6,6,1],[5,6,0],[0,0,6]]),"");
  ok("Active Gana profile is A",D.gana.activeProfile==="A","");
  ok("Observation: Profile A is exactly Profile B with bride and groom swapped (transpose)",differenceReport("A","B").aIsTransposeOfB,"");
  ok("Same-Gana cells score 6 in every profile",listProfiles().every(id=>{const m=getProfile(id).matrix;return m[0][0]===6&&m[1][1]===6&&m[2][2]===6}),"");
  ok("All scores lie between 0 and 6 in every profile",listProfiles().every(id=>getProfile(id).matrix.flat().every(v=>v>=0&&v<=6)),"");
  ok("Profile A, B and A0 each have a 3 x 3 total of 30",[A,B,A0].every(m=>m.flat().reduce((x,y)=>x+y,0)===30),"");
  // nine combinations, Profile A
  const nine=[["Deva","Deva",6],["Deva","Manushya",5],["Deva","Rakshasa",1],["Manushya","Deva",6],["Manushya","Manushya",6],["Manushya","Rakshasa",0],["Rakshasa","Deva",0],["Rakshasa","Manushya",0],["Rakshasa","Rakshasa",6]];
  nine.forEach(x=>{const r=getGanaRelationship(x[0],x[1]);ok("Profile A nine-combination check: "+x[0]+" bride, "+x[1]+" groom = "+x[2],A[r.brideId][r.groomId]===x[2],"")});
  // worked examples from the course
  const ex=[["Ashwini","Bharani",5],["Bharani","Ashwini",6],["Krittika","Ashwini",0],["Ashwini","Krittika",1],["Rohini","Hasta",6]];
  ex.forEach(e=>{const r=calculateGanaScore(NAMES.indexOf(e[0])+1,NAMES.indexOf(e[1])+1,"A");ok("Worked case "+e[0]+" (bride) – "+e[1]+" (groom), Profile A",r.score===e[2],r.score+" of 6")});
  ok("Orientation matters: swapping roles changes Deva–Manushya from 5 to 6 (Profile A)",calculateGanaScore(1,2,"A").score===5&&calculateGanaScore(2,1,"A").score===6,"");
  ok("reverseView reports the difference",reverseView(1,2,"A").differ===true&&reverseView(1,1,"A").differ===false,"");
  // 27 x 27
  const M=generateMatrix("A");
  ok("The 27 × 27 matrix has 729 cells",M.length===27&&M.every(r=>r.length===27),M.flat().length);
  ok("Every 27 × 27 cell equals the 3 × 3 value for its two Ganas",M.flat().every(c=>c.score===A[gid(c.brideGana)][gid(c.groomGana)]),"");
  ok("Each of the nine combinations occupies exactly 81 cells",(()=>{const k={};M.flat().forEach(c=>{const s=c.brideGana+"|"+c.groomGana;k[s]=(k[s]||0)+1});return Object.keys(k).length===9&&Object.values(k).every(v=>v===81)})(),"");
  ok("The 27 × 27 matrix is not symmetric under Profile A",M.some((r,i)=>r.some((c,j)=>c.score!==M[j][i].score)),"");
  ok("The diagonal (same Nakshatra) always scores 6",M.every((r,i)=>r[i].score===6),"");
  ok("Profile D (research, symmetric) gives a symmetric 27 × 27 matrix",(()=>{const m=generateMatrix("D");return m.every((r,i)=>r.every((c,j)=>c.score===m[j][i].score))})(),"");
  ok("Profile A has an asymmetric Deva/Manushya pair and a Deva/Rakshasa pair",asymmetryReport("A").pairs.length===2&&asymmetryReport("D").symmetric===true,"");
  // layered independence
  ok("Changing the profile does not change the allocation",[1,3,5,9,27].every(i=>getGanaByNakshatra(i).gana===data().nakshatra[i-1].gana),"");
  const ra=calculateGanaCompatibility(3,1,"A"),rb=calculateGanaCompatibility(3,1,"B");
  ok("Same Nakshatras, different profile: same Ganas, possibly different score",ra.bride.gana===rb.bride.gana&&ra.groom.gana===rb.groom.gana&&ra.score===0&&rb.score===1,ra.score+" vs "+rb.score);
  ok("Dosha: low-score flag at 0 and 1, not at 5 or 6 (Profile A)",calculateGanaCompatibility(3,1,"A").flags.lowScore&&calculateGanaCompatibility(1,3,"A").flags.lowScore&&!calculateGanaCompatibility(1,2,"A").flags.lowScore&&!calculateGanaCompatibility(1,1,"A").flags.lowScore,"");
  ok("Dosha: traditional flag only for a Rakshasa mix; Rakshasa–Rakshasa is not flagged",calculateGanaCompatibility(3,1,"A").flags.traditional&&!calculateGanaCompatibility(3,3,"A").flags.traditional&&!calculateGanaCompatibility(1,2,"A").flags.traditional,"");
  ok("The Dosha flag can be changed by the threshold without changing the score",(()=>{const a=calculateGanaCompatibility(1,3,"A",{threshold:0}),b=calculateGanaCompatibility(1,3,"A",{threshold:1});return a.score===b.score&&a.flags.lowScore===false&&b.flags.lowScore===true})(),"");
  ok("Exceptions are identified but not applied by default",ra.exceptions.length>0&&ra.exceptions.every(e=>e.status==="identified, not applied"),"");
  ok("A pair with no flag has no exception list",calculateGanaCompatibility(1,1,"A").exceptions.length===0,"");
  const ap=applyExceptions(ra,[{id:"t",school:"Test school",source:"test only",applies:()=>true}]);
  ok("Applying a user-supplied sourced exception never changes the raw score",ap.rawScore===ra.score&&ap.scoreChanged===false&&ap.exceptions.some(e=>e.status.startsWith("applied")),"");
  ok("A rule without school or source is ignored",applyExceptions(ra,[{id:"x",applies:()=>true}]).exceptions.every(e=>e.status==="identified, not applied"),"");
  ok("Research warning is shown for every unverified profile",ra.flags.researchWarning===true,"");
  // differences
  ok("Profile A vs A0 differ in two cells (162 of 729 ordered pairs)",(()=>{const d=differenceReport("A","A0");return d.differingCells.length===2&&d.ordered27x27Affected===162})(),"");
  ok("Profile A vs B differ in four cells (324 of 729 ordered pairs)",(()=>{const d=differenceReport("A","B");return d.differingCells.length===4&&d.ordered27x27Affected===324})(),"");
  ok("Distribution of the 729 ordered pairs under Profile A: 0 in 243, 1 in 81, 5 in 81, 6 in 324",JSON.stringify(distribution("A"))===JSON.stringify({0:243,1:81,5:81,6:324}),JSON.stringify(distribution("A")));
  ok("compareProfiles returns one score per profile",compareProfiles(1,3).length===listProfiles().length,"");
  // custom profile
  setProfileMatrix("C",[[6,4,2],[4,6,1],[2,1,6]]);ok("Custom Profile C can be edited and is read back",calculateGanaScore(1,2,"C").score===4,"");
  resetProfile("C");ok("Resetting Profile C restores the copy of Profile A",calculateGanaScore(1,2,"C").score===5,"");
  let bad=0;[[[6,6,6],[6,6,6]],[[6,6,6],[6,6,6],[6,6,7]],"x",null].forEach(m=>{try{setProfileMatrix("C",m)}catch(e){bad++}});try{setProfileMatrix("A",A)}catch(e){bad++}
  ok("Invalid matrices and edits to a fixed profile are rejected",bad===5,bad+" of 5");
  let thrown=0;[0,28,1.5,"a",null,undefined].forEach(x=>{try{calculateGanaScore(x,1,"A")}catch(e){thrown++}});
  ok("Invalid or missing Nakshatra input is rejected",thrown===6,thrown+" of 6");
  ok("Unknown Gana or profile is rejected",(()=>{let n=0;try{getGanaRelationship("Asura","Deva")}catch(e){n++}try{getProfile("Z")}catch(e){n++}return n===2})(),"");
  ok("CSV export has 28 lines and 28 columns",(()=>{const l=toCsv("A").trim().split("\n");return l.length===28&&l[0].split(",").length===28})(),"");
  return out}
window.GanaEngine={GANAS,NAMES,EXCEPTION_CATEGORIES,listProfiles,getProfile,setProfileMatrix,resetProfile,getGanaByNakshatra,listByGana,getGanaRelationship,calculateGanaScore,calculateGanaCompatibility,
  generate3x3,generateMatrix,reverseView,compareProfiles,differenceReport,asymmetryReport,distribution,applyExceptions,identifyExceptions,doshaFlags,toCsv,transpose,runTests};
})();

