TRADITIONS.SI10b.factors=TRADITIONS.SI10a.factors;
const STORE_KEY="dk_d10custom";
function customLoad(){try{const v=JSON.parse(localStorage.getItem(STORE_KEY)||"null");if(v&&Array.isArray(v.factors)){const t=TRADITIONS.X;if(v.name)t.name=String(v.name).slice(0,80);t.factors=v.factors.filter(x=>["varna","mahendra","streeDeergha","rajju","vedha"].includes(x)).map(id=>F(id,{varna:"Varna",mahendra:"Mahendra",streeDeergha:"Stree Deergha",rajju:"Rajju",vedha:"Vedha"}[id],"qualitative",{module:id==="streeDeergha"?"sd":id}));t.supplementary=["varna","mahendra","streeDeergha","rajju","vedha"].filter(x=>!t.factors.some(f=>f.id===x));if(v.profiles)Object.assign(t.profiles,v.profiles)}}catch(e){}}
function setCustom(obj){const o={name:obj.name,factors:obj.factors,profiles:obj.profiles};try{localStorage.setItem(STORE_KEY,JSON.stringify(o))}catch(e){}customLoad()}
function clearCustom(){try{localStorage.removeItem(STORE_KEY)}catch(e){}TRADITIONS.X.name="Custom tradition slot (you compose it)";TRADITIONS.X.factors=[];TRADITIONS.X.supplementary=[]}
