function getDashakootaTradition(id){const t=TRADITIONS[id];if(!t)throw ERR("MISSING_TRADITION","Unknown or missing Dashakoota tradition "+id);return t}
function getKootasInTradition(id){const t=getDashakootaTradition(id);return t.factors.map(f=>({id:f.id,name:f.label||f.name,type:f.type,max:f.max===undefined?null:f.max}))}
function getKootaRuleProfile(id,kootaId){const t=getDashakootaTradition(id),m={varna:["Varna",t.profiles.varna],mahendra:["Mahendra",t.profiles.mahendra],streeDeergha:["Stree Deergha",t.profiles.sd],rajju:["Rajju",t.profiles.rajju]}[kootaId];return m?{koota:m[0],profile:m[1]}:null}
const Tradition={MASTER:TRADITIONS,getDashakootaTradition,getKootasInTradition,getKootaRuleProfile,setCustom,clearCustom,list:()=>Object.values(TRADITIONS)};

/* ================= Comparison ================= */
function row(f,t,r){return Object.assign({id:f.id,name:f.label||f.name,inTradition:true,kind:f.type},r)}
function evalFactor(f,t,b,g,prof){ // b, g are normalised persons
  const p=Object.assign({},t.profiles,prof||{});
  if(f.type==="notComputed")return row(f,t,{status:"NOT_COMPUTED",detail:f.why,rawScore:null,max:null,evidence:"E – not computed because the rule is not verified for this tradition"});
  const id=f.module||f.id;
  if(id==="varna"){if(b.rashi===undefined||g.rashi===undefined)return row(f,t,{status:"INSUFFICIENT_DATA",detail:"Moon Rashi missing.",rawScore:null,max:f.max||null});
    const r=calculateVarnaScore(b.rashi+1,g.rashi+1,p.varna);return row(f,t,{status:r.score?"FAVOURABLE":"UNFAVOURABLE",detail:`${SIGNS[b.rashi]} (${r.compare.bride.varna}) with ${SIGNS[g.rashi]} (${r.compare.groom.varna}): ${r.relation}`,rawScore:f.type==="scored"?r.score:null,max:f.type==="scored"?1:null,profile:p.varna,evidence:EV[VARNA_PROFILES[p.varna].grade[0]]||"C",adjusted:null})}
  if(id==="mahendra"){const r=evaluateMahendraProfile({nakshatra:b.nak+1},{nakshatra:g.nak+1},p.mahendra);return row(f,t,{status:r.status,detail:`count ${r.primaryCount} (${r.profile})`,rawScore:null,max:null,profile:p.mahendra,evidence:EV.D,adjusted:null})}
  if(id==="sd"){const r=evaluateStreeDeerghaProfile({nakshatra:b.nak+1},{nakshatra:g.nak+1},p.sd);return row(f,t,{status:r.status,detail:`count ${r.primaryCount}, threshold ${r.threshold} (${r.profile})${r.boundaryCase?"; boundary case":""}`,rawScore:null,max:null,profile:p.sd,evidence:EV.D,adjusted:null})}
  if(id==="rajju"){const r=evaluateRajjuProfile({nakshatra:b.nak+1},{nakshatra:g.nak+1},p.rajju);return row(f,t,{status:f.type==="qualitative"?(r.sameRajju?"NOT_PRESENT (same Rajju)":"PRESENT (different Rajju)"):r.status,detail:`${r.brideRajju} with ${r.groomRajju}`,rawScore:null,max:null,profile:p.rajju,evidence:EV.C,adjusted:null,exceptionApplied:null})}
  if(id==="vedha"){const v=isVedha(b.nak+1,g.nak+1);return row(f,t,{status:f.type==="qualitative"?(v?"NOT_PRESENT (Vedha pair)":"PRESENT (no Vedha pair)"):(v?"DOSHA_PRESENT":"NO_DOSHA"),detail:v?`${NAK[b.nak]}–${NAK[g.nak]} is a listed pair`:"not a listed pair",rawScore:null,max:null,evidence:EV.C,adjusted:null})}
  if(id==="lab"){return row(f,t,{status:"SEE_LAB",detail:"Computed by its own module (see the Calculation Lab)",rawScore:null,max:f.max||null,evidence:"C/D"})}
  return row(f,t,{status:"NOT_COMPUTED",detail:"No module",rawScore:null,max:null})}
function evaluateTradition(traditionId,bride,groom,prof){
  const t=getDashakootaTradition(traditionId),b=person(bride),g=person(groom),rows=[];
  // Tradition A: reproduce the actual defined scoring from the Calculation Lab for the eight scored Kootas
  let lab=null;
  if(t.id==="A"&&window.LabUI&&LabUI._engine&&b.rashi!==undefined&&g.rashi!==undefined){
    lab=LabUI._engine.calc(LabUI._engine.PROFILES.A,{rashi:b.rashi,nak:b.nak,pada:b.pada||1},{rashi:g.rashi,nak:g.nak,pada:g.pada||1})}
  t.factors.forEach(f=>{
    if(lab&&f.module==="lab"){const lr=lab.rows.find(x=>x.name.toLowerCase().replace(/ /g,"")===f.name.toLowerCase().replace(/ /g,""));rows.push(row(f,t,{status:lr?(lr.dosha?"DOSHA_FLAG":lr.cls.toUpperCase()):"NOT_FOUND",detail:lr?lr.exp:"",rawScore:lr?lr.score:null,max:f.max,evidence:"C/D – Calculation Lab, Tradition A",adjusted:null}))}
    else rows.push(evalFactor(f,t,b,g,prof))});
  const supp=t.supplementary.map(id=>{const nm={varna:"Varna",mahendra:"Mahendra",streeDeergha:"Stree Deergha",rajju:"Rajju",vedha:"Vedha"}[id]||id;
    const r=evalFactor(F(id,nm,"supplementary",{module:id==="streeDeergha"?"sd":id,max:null}),t,b,g,prof);r.inTradition=false;r.kind="supplementary";r.includedInTotal=false;r.note="Not one of this tradition's ten factors: shown as a supplementary comparison and never added to a total.";return r});
  let total=null;
  if(t.total.defined&&lab)total={value:lab.total,max:36,note:"Reproduced from the Calculation Lab for the eight scored Kootas (the tradition's own defined total). Rajju and Vedha add nothing."};
  return {tradition:{id:t.id,name:t.name,source:t.source,grade:t.grade,verified:t.verified},rows,supplementary:supp,total,totalNote:t.total.note,factorCount:t.factors.length,engineVersion:VERSION,profiles:Object.assign({},t.profiles,prof||{}),
    summary:rows.filter(r=>r.status!=="NOT_COMPUTED"&&r.status!=="SEE_LAB").map(r=>`${r.name}: ${r.status}`)}}
function compareDashakootaTraditions(bride,groom,ids,prof){return safe(()=>{const list=(ids&&ids.length?ids:["A","SI10a","SI10b"]).map(id=>evaluateTradition(id,bride,groom,prof));
  const canon=s=>/^(QUALIFIES|FAVOURABLE|NO_DOSHA|PRESENT)/.test(s)?"favourable":/^(DOES_NOT_QUALIFY|UNFAVOURABLE|DOSHA|NOT_PRESENT)/.test(s)?"unfavourable":s;
  const diffs=[];["varna","mahendra","streeDeergha","rajju","vedha"].forEach(k=>{
    const cells=list.map(r=>{const m=r.rows.find(y=>y.id===k),x=m||r.supplementary.find(y=>y.id===k);return {member:!!m,outcome:x?canon(x.status):"n/a"}});
    if(new Set(cells.map(c=>c.outcome)).size>1)diffs.push({koota:k,kind:"outcome",values:list.map((r,i)=>({tradition:r.tradition.id,value:cells[i].outcome}))});
    if(new Set(cells.map(c=>c.member)).size>1)diffs.push({koota:k,kind:"membership",values:list.map((r,i)=>({tradition:r.tradition.id,value:cells[i].member?"one of its factors":"supplementary only"}))})});
  return {module:"DASHAKOOTA_COMPARISON",results:list,differences:diffs,overallStatus:"PROFILE_BASED_COMPARISON",total:null,note:"Each tradition is evaluated with its own rules. Results are shown side by side and are never merged or averaged."}})}
function calculateSelectedDashakoota(traditionId,bride,groom,prof){return safe(()=>evaluateTradition(traditionId,bride,groom,prof))}
function generateDashakootaReport(bride,groom,traditionId,prof){return safe(()=>{const b=person(bride),g=person(groom),ev=evaluateTradition(traditionId||"A",bride,groom,prof),p=ev.profiles;
  const mh=evaluateMahendraProfile(bride,groom,p.mahendra),sd=evaluateStreeDeerghaProfile(bride,groom,p.sd),rj=evaluateRajjuProfile(bride,groom,p.rajju);
  const vr=b.rashi!==undefined&&g.rashi!==undefined?generateVarnaReport(b.rashi+1,g.rashi+1,p.varna):null;
  const json={module:"DASHAKOOTA_DAY_10",selectedTradition:ev.tradition,ruleProfiles:p,engineVersion:VERSION,
    personA:{role:"bride",moonRashi:b.rashiName||null,nakshatra:b.nakName,pada:b.pada||null},personB:{role:"groom",moonRashi:g.rashiName||null,nakshatra:g.nakName,pada:g.pada||null},
    results:{varna:vr,mahendra:mh,streeDeergha:sd,rajju:rj},traditionRows:ev.rows,supplementary:ev.supplementary,total:ev.total,overallStatus:"PROFILE_BASED_COMPARISON",
    limitations:["Mahendra and Stree Deergha carry no points: no verified scoring source is held.","Exceptions are recorded with an evidence level and never applied automatically.","Verse, chapter and page references are not verified."],statement:STATEMENT};
  const L=[];L.push("DASHAKOOTA ADDITIONAL KOOTAS REPORT (ASTROSUTRAS, Day 10)");L.push("Selected tradition: "+ev.tradition.name+" | Source: "+ev.tradition.source+" | Verified: "+(ev.tradition.verified?"yes":"no"));
  L.push(`Person A (bride): ${b.nakName}${b.pada?" Pada "+b.pada:""}${b.rashiName?", Moon in "+b.rashiName:""}`);L.push(`Person B (groom): ${g.nakName}${g.pada?" Pada "+g.pada:""}${g.rashiName?", Moon in "+g.rashiName:""}`);
  L.push("Rule profiles: "+Object.entries(p).map(([k,v])=>k+"="+v).join(", ")+" | engine "+VERSION);
  if(vr)L.push("Varna: "+vr.interpretation+" ("+vr.rawScore+" of 1)");
  L.push(`Mahendra: ${mh.status} (count ${mh.primaryCount}, profile ${mh.profile}); qualitative, no points.`);
  L.push(`Stree Deergha: ${sd.status} (count ${sd.primaryCount}, threshold ${sd.threshold}, profile ${sd.profile})${sd.boundaryCase?" [boundary case]":""}; qualitative, no points.`);
  L.push(`Rajju: ${rj.brideRajju} with ${rj.groomRajju}: ${rj.status}; Vedha: ${rj.vedha?"listed pair (flag)":"no listed pair"}. No exception applied.`);
  L.push(ev.total?`Tradition total (reproduced from the Calculation Lab): ${ev.total.value} of 36 for the eight scored Kootas.`:"No total is created for this tradition: "+ev.totalNote);
  L.push("Raw results are shown as calculated; no adjusted score exists.");L.push("");L.push(STATEMENT);
  json.text=L.join("\n");return json})}
const Comparison={evaluateTradition,compareDashakootaTraditions,calculateSelectedDashakoota,generateDashakootaReport};
Tradition.calculateSelectedDashakoota=calculateSelectedDashakoota;Tradition.compareDashakootaTraditions=compareDashakootaTraditions;Tradition.generateDashakootaReport=generateDashakootaReport;

/* ================= twenty worked cases (all engine-validated in the tests) ================= */
const C=(label,bn,bp,gn,gp)=>({label,bride:{nakshatra:bn,pada:bp},groom:{nakshatra:gn,pada:gp}});
const CASES=[
 C("Same Varna","Rohini",2,"Hasta",1),C("Different Varna, favourable","Bharani",1,"Pushya",4),C("Varna with bride/groom roles reversed","Pushya",4,"Bharani",1),
 C("Mahendra count 4","Ashwini",1,"Rohini",1),C("Mahendra count 7","Bharani",2,"Pushya",1),C("Mahendra count 10","Krittika",3,"Uttara Phalguni",2),C("Mahendra count 13","Mrigashira",3,"Anuradha",2),
 C("Mahendra count 16","Punarvasu",4,"Shravana",3),C("Mahendra count 19","Hasta",2,"Rohini",4),C("Mahendra count 22","Anuradha",1,"Purva Phalguni",3),C("Mahendra count 25","Shravana",2,"Mula",1),
 C("Mahendra non-qualifying count","Ashwini",3,"Mrigashira",2),C("Stree Deergha count below 13","Ashwini",2,"Ashlesha",1),C("Stree Deergha count exactly 13","Chitra",3,"Uttara Bhadrapada",4),
 C("Stree Deergha count above 13","Bharani",4,"Uttara Ashadha",3),C("Stree Deergha boundary crossing (Revati to Ashwini)","Jyeshtha",1,"Pushya",3),
 C("Same Rajju, same Nakshatra","Ashwini",1,"Ashwini",3),C("Same Rajju, different Nakshatra","Ashlesha",2,"Mula",3),C("Different Rajju","Ashwini",2,"Rohini",3),C("Varna and Mahendra favourable, Rajju flagged","Ashwini",1,"Magha",1)];

/* ================= validation ================= */
function runTests(){
  const R=[],T=(name,fn)=>{try{const d=fn();R.push({name,pass:d===true||d===undefined||(d&&d.ok!==false&&d!==false),detail:typeof d==="string"?d:(d&&d.detail)||"ok"})}catch(e){R.push({name,pass:false,detail:"EXCEPTION "+(e.code||"")+": "+e.message})}};
  const eq=(a,b,m)=>{if(a!==b)throw new Error((m||"")+" expected "+b+" got "+a);return true};
  const throwsCode=(fn,code)=>{try{fn()}catch(e){if(e.code===code)return true;throw new Error("expected "+code+" got "+(e.code||e.message))}throw new Error("no error; expected "+code)};
  const d=D(),LE=window.LabUI&&LabUI._engine,labPair=(bn,bp,gn,gp,br,gr)=>LE.calc(LE.PROFILES.A,{rashi:br,nak:bn,pada:bp},{rashi:gr,nak:gn,pada:gp});
  /* --- Varna --- */
  T("Varna: all twelve Rashis have a valid Varna",()=>{for(let i=1;i<=12;i++)if(!VRANK[getRashiVarna(i).varna])throw new Error("sign "+i)});
  T("Varna: four groups of exactly three signs each",()=>{const c={};for(let i=1;i<=12;i++){const v=getRashiVarna(i).varna;c[v]=(c[v]||0)+1}VARNAS.forEach(v=>eq(c[v],3,v));return "3/3/3/3"});
  T("Varna: tradition-A.json agrees with the independent element table",()=>{for(let i=0;i<12;i++)eq(d.rashi[i].varna,INDEP_VARNA_BY_ELEMENT[ELEMENT[i]],SIGNS[i])});
  T("Varna: every sign appears once (no duplicate assignment of a sign)",()=>eq(new Set(d.rashi.map(r=>r.name)).size,12));
  T("Varna: bride Taurus, groom Aries scores 1",()=>eq(calculateVarnaScore(2,1,"A").score,1));
  T("Varna: bride Cancer, groom Aries scores 0",()=>eq(calculateVarnaScore(4,1,"A").score,0));
  T("Varna: equal Varna scores 1 (Taurus, Virgo)",()=>eq(calculateVarnaScore(2,6,"A").score,1));
  T("Varna: reverse combination differs (Taurus/Aries vs Aries/Taurus)",()=>eq(calculateVarnaScore(1,2,"A").score,0));
  T("Varna: profile R is the transpose of profile A over all 144 pairs",()=>{for(let b=1;b<=12;b++)for(let g=1;g<=12;g++)eq(calculateVarnaScore(b,g,"R").score,calculateVarnaScore(g,b,"A").score,b+","+g)});
  T("Varna: symmetric profile S is symmetric",()=>{for(let b=1;b<=12;b++)for(let g=1;g<=12;g++)eq(calculateVarnaScore(b,g,"S").score,calculateVarnaScore(g,b,"S").score)});
  T("Varna: 4×4 matrix has 10 ones and 6 zeros",()=>{const m=varnaMatrix4("A").flat();eq(m.filter(x=>x.score).length,10);eq(m.filter(x=>!x.score).length,6)});
  T("Varna: 12×12 matrix is 144 cells",()=>{const m=varnaMatrix12("A");eq(m.length,12);eq(m.flat().length,144)});
  T("Varna: engine agrees with the Calculation Lab for all 144 pairs",()=>{for(let b=0;b<12;b++)for(let g=0;g<12;g++){const lab=labPair(0,1,0,1,b,g).rows.find(r=>r.name==="Varna").score;eq(calculateVarnaScore(b+1,g+1,"A").score,lab,SIGNS[b]+"/"+SIGNS[g])}return "144 of 144"});
  T("Varna: the report carries the no-caste caution and has no caste field",()=>{const r=generateVarnaReport(2,1,"A");if(!/caste/i.test(r.caution))throw new Error("caution missing");if(Object.keys(r).some(k=>/caste|community|status/i.test(k)))throw new Error("forbidden key")});
  /* --- Mahendra --- */
  T("Mahendra: Nakshatra indices run 0 to 26",()=>{eq(nakIndex("Ashwini"),0);eq(nakIndex("Revati"),26);eq(new Set(NAK.map(nakIndex)).size,27)});
  T("Mahendra: Ashwini to Bharani counts 2",()=>eq(calculateMahendraCount(0,1),2));
  T("Mahendra: Revati to Ashwini wraps to 2",()=>eq(calculateMahendraCount(26,0),2));
  T("Mahendra: same Nakshatra counts 1 and does not qualify",()=>{eq(calculateMahendraCount(5,5),1);eq(checkMahendraFavourablePosition(1),false)});
  MAH_FAV.forEach(c=>T(`Mahendra: count ${c} is recognised under profile M1`,()=>{const r=evaluateMahendraProfile({nakshatra:1},{nakshatra:c},"M1");eq(r.primaryCount,c);eq(r.qualifies,true)}));
  T("Mahendra: non-qualifying counts are not labelled Dosha (all 27 grooms)",()=>{for(let g=1;g<=27;g++){const r=evaluateMahendraProfile({nakshatra:1},{nakshatra:g},"M1");if(r.dosha!==null||/DOSHA/.test(r.status))throw new Error("Dosha label at "+g)}});
  T("Mahendra: 216 qualifying cells of 729 (8 per row)",()=>{const m=mahMatrix("M1").flat();eq(m.length,729);eq(m.filter(x=>x.qualifies).length,216);mahMatrix("M1").forEach(r=>eq(r.filter(x=>x.qualifies).length,8))});
  T("Mahendra: qualification is the same in both directions even though the counts differ",()=>{const a=mahMatrix("M1"),b=mahMatrix("M2");for(let i=0;i<27;i++)for(let j=0;j<27;j++)eq(a[i][j].qualifies,b[i][j].qualifies);return "forward count c, reverse count 29−c, both ≡ 1 (mod 3)"});
  T("Mahendra: reverse direction gives a different count (Ashwini–Rohini 4 vs 25)",()=>{const r=evaluateMahendraProfile({nakshatra:1},{nakshatra:4},"M1");eq(r.countBrideToGroom,4);eq(r.countGroomToBride,25)});
  T("Mahendra: exclusive counting (M4) gives a different verdict, showing why inclusive counting is needed",()=>{const r=evaluateMahendraProfile({nakshatra:1},{nakshatra:4},"M4");eq(r.qualifies,false)});
  T("Mahendra: no points are assigned",()=>{const r=evaluateMahendraProfile({nakshatra:1},{nakshatra:4},"M1");eq(r.rawScore,null);eq(r.max,null)});
  /* --- Stree Deergha --- */
  T("Stree Deergha: bride-to-groom direction and inclusive counting (Ashwini → Rohini = 4)",()=>eq(calculateStreeDeerghaCount(0,3),4));
  T("Stree Deergha: count 12 is below the > 13 threshold",()=>eq(checkStreeDeerghaThreshold(12,"SD1"),false));
  T("Stree Deergha: count 13 is a boundary case (not qualifying under SD1, qualifying under SD2)",()=>{eq(checkStreeDeerghaThreshold(13,"SD1"),false);eq(checkStreeDeerghaThreshold(13,"SD2"),true);const r=evaluateStreeDeerghaProfile({nakshatra:1},{nakshatra:13},"SD1");eq(r.primaryCount,13);eq(r.boundaryCase,true)});
  T("Stree Deergha: count 14 qualifies under SD1",()=>eq(checkStreeDeerghaThreshold(14,"SD1"),true));
  T("Stree Deergha: Revati to Ashwini wraps to 2",()=>eq(calculateStreeDeerghaCount(26,0),2));
  T("Stree Deergha: reverse count is 29 minus the forward count",()=>{const e=evaluateBrideGroomDirection({nakshatra:5},{nakshatra:20});eq(e.brideToGroom+e.groomToBride,29)});
  T("Stree Deergha: matrix is directional (not symmetric) under SD1",()=>{const m=sdMatrix("SD1");let asym=0;for(let i=0;i<27;i++)for(let j=0;j<27;j++)if(m[i][j].qualifies!==m[j][i].qualifies)asym++;if(!asym)throw new Error("symmetric");return asym+" asymmetric cells"});
  T("Stree Deergha: threshold changes only when the profile changes",()=>{const a=evaluateStreeDeerghaProfile({nakshatra:1},{nakshatra:13},"SD1"),b=evaluateStreeDeerghaProfile({nakshatra:1},{nakshatra:13},"SD2");eq(a.primaryCount,b.primaryCount);eq(a.qualifies,false);eq(b.qualifies,true)});
  T("Stree Deergha: qualifying cells SD1 378, SD2 405, SD3 486, SD4 513, SD6 567",()=>{[["SD1",378],["SD2",405],["SD3",486],["SD4",513],["SD6",567]].forEach(([p,n])=>eq(sdMatrix(p).flat().filter(x=>x.qualifies).length,n,p))});
  T("Stree Deergha: reverse profile SD5 is the transpose of SD1",()=>{const a=sdMatrix("SD1"),b=sdMatrix("SD5");for(let i=0;i<27;i++)for(let j=0;j<27;j++)eq(b[i][j].qualifies,a[j][i].qualifies)});
  T("Stree Deergha: no points and no Dosha label",()=>{const r=evaluateStreeDeerghaProfile({nakshatra:1},{nakshatra:5},"SD1");eq(r.rawScore,null);eq(r.dosha,null)});
  /* --- Rajju and Vedha --- */
  T("Rajju: all 27 Nakshatras have exactly one valid Rajju",()=>{for(let i=1;i<=27;i++)if(!RAJJUS.includes(getRajjuByNakshatra(i).rajju))throw new Error(i)});
  T("Rajju: group sizes are 6, 6, 6, 6 and 3",()=>{const c={};d.nakshatra.forEach(n=>c[n.rajju]=(c[n.rajju]||0)+1);eq([c.Pada,c.Kati,c.Nabhi,c.Kantha,c.Siro].join(","),"6,6,6,6,3")});
  T("Rajju: tradition-A.json agrees with the independent published lists",()=>{RAJJUS.forEach(r=>RAJJU_LISTS[r].forEach(n=>eq(d.nakshatra[NAK.indexOf(n)].rajju,r,n)));eq(Object.values(RAJJU_LISTS).flat().length,27)});
  T("Rajju: the published table follows a nine-step zigzag (observation, not the source of the table)",()=>{const z=["Pada","Kati","Nabhi","Kantha","Siro","Kantha","Nabhi","Kati","Pada"];for(let i=0;i<27;i++)eq(d.nakshatra[i].rajju,z[i%9],NAK[i])});
  T("Rajju: same group is identified (Ashwini, Magha)",()=>eq(identifyRajjuDosha(1,10).dosha,true));
  T("Rajju: different group is identified (Ashwini, Rohini)",()=>eq(identifyRajjuDosha(1,4).dosha,false));
  T("Rajju: same-group matrix is symmetric with 153 cells (4×36 + 9)",()=>{const m=rajjuMatrix();let n=0;for(let i=0;i<27;i++)for(let j=0;j<27;j++){eq(m[i][j].same,m[j][i].same);if(m[i][j].same)n++}eq(n,153)});
  T("Rajju: engine agrees with the Calculation Lab for all 729 pairs",()=>{for(let a=0;a<27;a++)for(let b=0;b<27;b++){const rows=labPair(a,1,b,1,0,0).rows,lr=rows.find(r=>r.name==="Rajju").dosha,lv=rows.find(r=>r.name==="Vedha").dosha;eq(identifyRajjuDosha(a+1,b+1).dosha,lr,NAK[a]+"/"+NAK[b]);eq(isVedha(a+1,b+1),lv,"vedha "+NAK[a]+"/"+NAK[b])}return "729 of 729 (Rajju and Vedha)"});
  T("Rajju: in this table no two different Nakshatras that share a Moon sign share a Rajju group",()=>{let n=0;for(let a=0;a<27;a++)for(let b=0;b<27;b++)if(a!==b&&d.nakshatra[a].rajju===d.nakshatra[b].rajju&&coverage(a).some(r=>coverage(b).includes(r)))n++;eq(n,0);return "0 such pairs"});
  T("Vedha: in this table every one of the 14 listed pairs is also a same-Rajju pair (so Vedha never flags without Rajju)",()=>{d.vedha.pairs.forEach(p=>eq(d.nakshatra[NAK.indexOf(p[0])].rajju,d.nakshatra[NAK.indexOf(p[1])].rajju,p.join("–")))});
  T("Rajju: Vedha list has 14 pairs and is symmetric",()=>{eq(d.vedha.pairs.length,14);let n=0;for(let a=1;a<=27;a++)for(let b=1;b<=27;b++){eq(isVedha(a,b),isVedha(b,a));if(isVedha(a,b))n++}eq(n,28)});
  T("Rajju: split Nakshatra boundaries (Krittika Pada 1 Aries, Pada 2 Taurus)",()=>{eq(padaRashi(2,1),0);eq(padaRashi(2,2),1);eq(padaRashi(1,4),0);eq(padaRashi(26,4),11);eq(padaRashi(0,1),0)});
  T("Rajju: exactly nine Nakshatras are split across two Rashis",()=>{const s=NAK.map((_,i)=>i).filter(i=>coverage(i).length===2).map(i=>NAK[i]);eq(s.join(","),"Krittika,Mrigashira,Punarvasu,Uttara Phalguni,Chitra,Vishakha,Uttara Ashadha,Dhanishta,Purva Bhadrapada")});
  T("Rajju: same Rajju does not invoke an exception (adjusted status = raw status)",()=>{const r=evaluateRajjuProfile({nakshatra:"Ashwini",pada:1},{nakshatra:"Magha",pada:1},"R");eq(r.exceptionApplied,null);eq(r.adjustedStatus,r.rawStatus);eq(r.exceptionChecks.every(c=>c.active===false&&c.changesDoshaStatus===false&&c.restoresScore===false),true)});
  T("Rajju: profile A attaches no exceptions; profile R lists candidates but applies none",()=>{eq(evaluateRajjuProfile({nakshatra:1},{nakshatra:10},"A").exceptionChecks.length,0);eq(evaluateRajjuProfile({nakshatra:1},{nakshatra:10},"R").exceptionChecks.length,CANDIDATES.length)});
  T("Rajju: unverified exceptions cannot be silently activated",()=>throwsCode(()=>checkRajjuExceptions({nakshatra:1},{nakshatra:10},{applyUnverified:true}),"UNVERIFIED_EXCEPTION"));
  T("Rajju: profile variations are preserved (A and R give the same status, R adds the study list)",()=>eq(evaluateRajjuProfile({nakshatra:1},{nakshatra:10},"A").status,evaluateRajjuProfile({nakshatra:1},{nakshatra:10},"R").status));
  /* --- tradition and comparison (integration) --- */
  T("Tradition A returns exactly its ten configured factors (8 scored + Rajju + Vedha)",()=>{const k=getKootasInTradition("A");eq(k.length,10);eq(k.filter(x=>x.type==="scored").length,8);eq(k.filter(x=>x.type==="passDosha").map(x=>x.id).join(),"rajju,vedha");eq(k.reduce((s,x)=>s+(x.max||0),0),36)});
  T("South Indian profile returns exactly its ten Poruthams in order",()=>eq(getKootasInTradition("SI10a").map(x=>x.id).join(),"dina,gana,mahendra,streeDeergha,yoni,rasi,rasiAdhipati,vasya,rajju,vedha"));
  T("No extra Koota is added automatically (evaluation rows = configured factors)",()=>{["A","SI10a","SI10b"].forEach(id=>{const r=evaluateTradition(id,{nakshatra:"Rohini",pada:2},{nakshatra:"Hasta",pada:1});eq(r.rows.length,getKootasInTradition(id).length,id)})});
  T("A factor absent from the tradition is supplementary and excluded from totals (Mahendra in A, Varna in SI10a)",()=>{const a=evaluateTradition("A",{nakshatra:"Rohini",pada:2},{nakshatra:"Hasta",pada:1}),s=evaluateTradition("SI10a",{nakshatra:"Rohini",pada:2},{nakshatra:"Hasta",pada:1});eq(a.supplementary.map(x=>x.id).join(),"mahendra,streeDeergha");eq(a.supplementary.every(x=>x.includedInTotal===false&&x.inTradition===false),true);eq(s.supplementary[0].id,"varna");eq(s.supplementary[0].includedInTotal,false)});
  T("Tradition A total is reproduced from the Calculation Lab, not invented here",()=>{const r=evaluateTradition("A",{nakshatra:"Ashwini",pada:1},{nakshatra:"Bharani",pada:1});eq(r.total.max,36);const lab=labPair(0,1,1,1,0,0);eq(r.total.value,lab.total)});
  T("No invented total for the South Indian profiles",()=>{eq(evaluateTradition("SI10a",{nakshatra:1,pada:1},{nakshatra:3,pada:1}).total,null);eq(compareDashakootaTraditions({nakshatra:1,pada:1},{nakshatra:3,pada:1}).total,null)});
  T("Different traditions produce independent results (changing SD profile in SI10b does not change SI10a or A)",()=>{const b={nakshatra:"Chitra",pada:3},g={nakshatra:"Uttara Bhadrapada",pada:4};const x=evaluateTradition("SI10a",b,g),y=evaluateTradition("SI10b",b,g);eq(x.rows.find(r=>r.id==="streeDeergha").status,"DOES_NOT_QUALIFY");eq(y.rows.find(r=>r.id==="streeDeergha").status,"QUALIFIES");eq(evaluateTradition("A",b,g).supplementary.find(r=>r.id==="streeDeergha").status,"DOES_NOT_QUALIFY")});
  T("Source, profile and engine version are recorded in every result",()=>{const r=evaluateTradition("SI10a",{nakshatra:1,pada:1},{nakshatra:5,pada:1});eq(r.engineVersion,VERSION);if(!r.tradition.source||!r.profiles.sd)throw new Error("missing")});
  T("The same horoscope is evaluated under several traditions and differences are listed",()=>{const c=compareDashakootaTraditions({nakshatra:"Chitra",pada:3},{nakshatra:"Uttara Bhadrapada",pada:4});eq(c.results.length,3);if(!c.differences.some(x=>x.koota==="streeDeergha"))throw new Error("no SD difference")});
  T("Not-computed Poruthams are labelled as such, never given an invented result",()=>{const r=evaluateTradition("SI10a",{nakshatra:1,pada:1},{nakshatra:5,pada:1});["dina","gana","yoni","rasi","rasiAdhipati","vasya"].forEach(k=>eq(r.rows.find(x=>x.id===k).status,"NOT_COMPUTED",k))});
  T("The final report contains the mandated statement",()=>{const r=generateDashakootaReport({nakshatra:1,pada:1},{nakshatra:10,pada:1},"A");if(!r.text.includes(STATEMENT))throw new Error("statement missing")});
  T("No automatic medical, fertility or longevity claim in any generated interpretation",()=>{const t=JSON.stringify([generateMahendraReport({nakshatra:1},{nakshatra:4},"M1"),generateStreeDeerghaReport({nakshatra:1},{nakshatra:15},"SD1"),generateRajjuReport({nakshatra:1},{nakshatra:10},"A")]);if(/will (die|conceive|have children)|guarantee(s|d)? (fertility|longevity)/i.test(t))throw new Error("forbidden phrase")});
  /* --- error handling --- */
  T("Error: missing Nakshatra",()=>throwsCode(()=>person({pada:1}),"MISSING_NAKSHATRA"));
  T("Error: invalid Pada",()=>throwsCode(()=>person({nakshatra:1,pada:5}),"INVALID_PADA"));
  T("Error: inconsistent Rashi and Pada (Krittika Pada 1 is Aries, not Taurus)",()=>throwsCode(()=>person({nakshatra:"Krittika",pada:1,rashi:"Taurus"}),"INCONSISTENT_RASHI"));
  T("Error: missing tradition",()=>throwsCode(()=>getDashakootaTradition("NOPE"),"MISSING_TRADITION"));
  T("Error: unknown profile",()=>throwsCode(()=>mahProfile("ZZ"),"UNKNOWN_PROFILE"));
  T("Error: evaluate functions return INSUFFICIENT_DATA instead of guessing",()=>eq(evaluateMahendraProfile({},{nakshatra:1},"M1").status,"INSUFFICIENT_DATA"));
  /* --- the twenty cases --- */
  T("All 20 worked cases are real Nakshatra/Pada/Rashi combinations and evaluate without error",()=>{eq(CASES.length,20);CASES.forEach(c=>{person(c.bride);person(c.groom)})});
  T("Worked cases hit their headline conditions (counts 4,7,10,13,16,19,22,25; SD 13; wrap; Rajju)",()=>{const cnt=i=>{const c=CASES[i];return count(nakIndex(c.bride.nakshatra),nakIndex(c.groom.nakshatra))};[[3,4],[4,7],[5,10],[6,13],[7,16],[8,19],[9,22],[10,25],[13,13],[14,20],[15,18]].forEach(([i,n])=>eq(cnt(i),n,"case "+(i+1)));eq(cnt(11),5);eq(cnt(12),9);
    const rj=i=>identifyRajjuDosha(CASES[i].bride.nakshatra,CASES[i].groom.nakshatra).dosha;eq(rj(16),true);eq(rj(17),true);eq(rj(18),false);eq(rj(19),true);
    eq(calculateVarnaScore(person(CASES[0].bride).rashi+1,person(CASES[0].groom).rashi+1,"A").score,1)});
  return R}

window.DashakootaEngines={VERSION,Varna,Mahendra,StreeDeergha,Rajju,Tradition,Comparison,runTests,CASES,NAK,NAKHI,SIGNS,SIGNHI,ELEMENT,LORD,VHI,RHI,RBODY,RAJJUS,VARNAS,VRANK,MAH_FAV,EV,STATEMENT,VARNA_CAUTION,person,nakIndex,rashiIndex,padaRashi,coverage,padasIn,count,path,rel,isVedha};
