/* ===================== data helpers ===================== */
function person(nak,pada){
 if(nak===undefined||nak===null||nak==="")throw new TE("MISSING_NAKSHATRA","Nakshatra is missing.");
 if(!Number.isInteger(nak)||nak<0||nak>26)throw new TE("INVALID_NAKSHATRA","Nakshatra index must be an integer 0 to 26 (Ashwini = 0, Revati = 26), got "+nak);
 if(pada===undefined||pada===null||pada==="")throw new TE("MISSING_PADA","Pada is missing.");
 if(!Number.isInteger(pada)||pada<1||pada>4)throw new TE("INVALID_PADA","Pada must be 1 to 4, got "+pada);
 const L=nak*40/3+(pada-1)*10/3+5/3,id=LE().identify(L,true);
 if(id.nak!==nak||id.pada!==pada)throw new TE("INCONSISTENT_NAKSHATRA_PADA","Nakshatra/Pada midpoint failed validation.");
 return Object.assign({},id,{nak,pada,name:D().nakshatra[nak].name,rashiName:SIGNS[id.rashi]});
}
function personFromLongitude(L){const id=LE().identify(L);return Object.assign({},id,{name:D().nakshatra[id.nak].name,rashiName:SIGNS[id.rashi]})}
function allPersons(){const a=[];for(let n=0;n<27;n++)for(let p=1;p<=4;p++)a.push(person(n,p));return a}
const nk=i=>D().nakshatra[i];
const lab=(b,g,extra)=>LE().calc(LE().PROFILES[extra?"A":"ashtakoota"],b,g);
const labRow=(b,g,name,extra)=>lab(b,g,extra).rows.find(r=>r.name===name);
const LORD=["Mars","Venus","Mercury","Moon","Sun","Mercury","Venus","Mars","Jupiter","Saturn","Saturn","Jupiter"];
const SOFT=D=>D;

/* ===================== KootaRuleRegistry (plug-ins) =====================
   KootaPlugin = {kootaId, concept, name, hi, kind, input, direction, def(cfg), calc(bride,groom,cfg)} -> standard result */
const OK=(x)=>x?true:false;
function res(k,b,g,o){return Object.assign({kootaId:k.id,concept:k.concept,name:k.name,hi:k.hi,kind:k.kind,input:{bride:b.name+" P"+b.pada+" / "+b.rashiName,groom:g.name+" P"+g.pada+" / "+g.rashiName},method:k.def(o.cfg||{}).rule,directional:k.directional,evidence:k.evidence,sources:k.sources},o)}
const KOOTAS={};
function addK(k){KOOTAS[k.id]=k}
/* ---- Ashtakoota / Tradition A (delegated to the Calculation Lab so that both implementations stay identical) ---- */
[["varna","varna","Varna","वर्ण","Moon Rashi","bride/groom (groom's class equal or higher)",1,"Rashi-based class comparison; directional in the course profile; Varna is a symbolic classification, never a judgement of caste or worth."],
 ["vashya","vashya","Vashya","वश्य","Moon Rashi group","bride row / groom column",2,"Five Vashya groups, matrix score 0 to 2 (Profile A)."],
 ["tara","tara","Tara","तारा","Janma Nakshatra","both directions",3,"Count in both directions, divide by 9, inauspicious remainders 3, 5, 7 give 0 (1.5 each direction)."],
 ["yoni","yoni","Yoni","योनि","Janma Nakshatra","bride row / groom column",4,"Fourteen Yonis, matrix score 0 to 4 (Profile A)."],
 ["graha_maitri","maitri","Graha Maitri","ग्रह मैत्री","Moon-sign lords","both viewpoints",5,"Natural friendship of the two Moon-sign lords, 0 to 5."],
 ["gana","gana","Gana","गण","Janma Nakshatra","bride row / groom column",6,"Deva/Manushya/Rakshasa matrix 0 to 6 (Profile A)."],
 ["bhakoot","bhakoot","Bhakoot","भकूट","Moon Rashi distance","counts 1/1, 3/11, 4/10, 7/7 score 7; 2/12, 5/9, 6/8 score 0",7,"Pair of inclusive Rashi counts; symmetric result."],
 ["nadi","nadi","Nadi","नाड़ी","Janma Nakshatra","symmetric",8,"Same Nadi 0, different Nadi 8."]
].forEach(r=>addK({id:r[0],concept:r[1],name:r[2],hi:r[3],kind:"score",input:r[4],directional:["varna","vashya","yoni","gana"].includes(r[0]),evidence:5,sources:["S_COURSE","S_LEAD_MC"],max:r[6],labName:r[2],
  def:()=>({input:r[4],direction:r[5],scale:"points 0 to "+r[6],rule:r[7]}),
  calc(b,g,cfg){const row=labRow(b,g,r[2],false);return res(this,b,g,{cfg,raw:row.score,max:row.max,status:row.dosha?"DOSHA_FLAGGED":"SCORED",label:row.score+" / "+row.max,detail:row.exp,dosha:!!row.dosha})}}));
[["rajju","rajju","Rajju","रज्जु","Janma Nakshatra","symmetric in the course profile","Same Rajju group = Dosha (pass/Dosha, no points); Pada, Kati, Nabhi, Kantha, Siro."],
 ["vedha","vedha","Vedha","वेध","Janma Nakshatra","symmetric pair list","A listed Vedha pair = Dosha (pass/Dosha, no points)."]
].forEach(r=>addK({id:r[0],concept:r[1],name:r[2],hi:r[3],kind:"passdosha",input:r[4],directional:false,evidence:5,sources:["S_COURSE"],max:null,labName:r[2],
  def:()=>({input:r[4],direction:r[5],scale:"pass / Dosha",rule:r[6]}),
  calc(b,g,cfg){const row=labRow(b,g,r[2],true);return res(this,b,g,{cfg,raw:null,max:null,status:row.dosha?"DOSHA":"PASS",label:row.dosha?"Dosha":"Pass",detail:row.exp,dosha:!!row.dosha})}}));
/* ---- South Indian (Tamil) factors ---- */
const DINA_LIST=[2,4,6,8,9,11,13,15,18,20,24,26];
function dinaOK(c,cfg){return cfg.dina==="list"?DINA_LIST.includes(c):[0,2,4,6,8].includes(c%9)}
const SD=cfg=>cfg.sd||{op:"gt",n:13};
function sdOK(c,cfg){const s=SD(cfg);return s.op==="gt"?c>s.n:c>=s.n}
const Q=(k,b,g,cfg,ok,det,extra)=>res(k,b,g,Object.assign({cfg,raw:null,max:null,status:ok?"QUALIFIES":"DOES_NOT_QUALIFY",label:ok?"Qualifies":"Does not qualify",detail:det,qualifies:ok},extra||{}));
const BASE=(id,concept,name,hi,input,dir,evidence,sources)=>({id,concept,name,hi,kind:"qualify",input,directional:!/symmetric|both viewpoints/.test(dir),evidence,sources});
addK(Object.assign(BASE("dina","tara","Dina","दिन","Janma Nakshatra","bride to groom",5,["S_HINDUTONE","S_TUNING"]),{
 def:cfg=>({input:"Janma Nakshatra",direction:"bride to groom, forward, inclusive",scale:"qualifies / does not qualify",rule:cfg.dina==="list"?"Qualifies when the inclusive count is in the listed set "+DINA_LIST.join(", ")+" (variant reported by one source)":"Qualifies when the inclusive count divided by 9 leaves remainder 2, 4, 6, 8 or 0 (commonly published remainder rule; sources differ)"}),
 calc(b,g,cfg){const c=fwd(b.nak,g.nak);return Q(this,b,g,cfg,dinaOK(c,cfg),`Count bride to groom = ${c}; remainder after dividing by 9 = ${c%9}${cfg.dina==="list"?"; in the listed set: "+(DINA_LIST.includes(c)?"yes":"no"):""}.`,{count:c})}}));
addK(Object.assign(BASE("mahendra","mahendra","Mahendra","महेन्द्र","Janma Nakshatra","bride to groom",5,["S_VEDICBIRTH_M"]),{
 def:()=>({input:"Janma Nakshatra",direction:"bride to groom, forward, inclusive",scale:"qualifies / does not qualify",rule:"Qualifies when the inclusive count is 4, 7, 10, 13, 16, 19, 22 or 25"}),
 calc(b,g,cfg){const c=fwd(b.nak,g.nak),ok=[4,7,10,13,16,19,22,25].includes(c);return Q(this,b,g,cfg,ok,`Count bride to groom = ${c}; ${ok?"in":"not in"} the favourable list. A non-qualifying count is not a Dosha.`,{count:c})}}));
addK(Object.assign(BASE("stree_deergha","stree_deergha","Stree Deergha","स्त्री दीर्घ","Janma Nakshatra","bride to groom",5,["S_VEDICBIRTH_S"]),{
 def:cfg=>({input:"Janma Nakshatra",direction:"bride to groom, forward, inclusive",scale:"qualifies / does not qualify",rule:"Qualifies when the inclusive count is "+(SD(cfg).op==="gt"?"greater than ":"at least ")+SD(cfg).n+(SD(cfg).n===7?" (variant carried from earlier course text, source unverified)":" (commonly cited threshold)")}),
 calc(b,g,cfg){const c=fwd(b.nak,g.nak),ok=sdOK(c,cfg);return Q(this,b,g,cfg,ok,`Count bride to groom = ${c}; threshold ${SD(cfg).op==="gt"?">":">="} ${SD(cfg).n}. Traditional symbolic reading only; not a prediction.`,{count:c})}}));
const DERIVED_NOTE="Threshold derived by the course from its Tradition A table; not a published Tamil rule (Level 7).";
addK(Object.assign(BASE("gana_t","gana","Gana (Porutham)","गण","Janma Nakshatra","bride to groom",7,["S_COURSE","S_HINDUTONE"]),{
 def:cfg=>({input:"Janma Nakshatra",direction:"bride row / groom column",scale:"qualifies / does not qualify",rule:"Qualifies when the Tradition A Gana matrix gives at least "+(cfg.ganaMin||5)+" of 6. "+DERIVED_NOTE}),
 calc(b,g,cfg){const s=labRow(b,g,"Gana",false).score,ok=s>=(cfg.ganaMin||5);return Q(this,b,g,cfg,ok,`Tradition A Gana score ${s}/6 (${nk(b.nak).gana} bride, ${nk(g.nak).gana} groom). ${DERIVED_NOTE}`)}}));
addK(Object.assign(BASE("yoni_t","yoni","Yoni (Porutham)","योनि","Janma Nakshatra","bride to groom",7,["S_COURSE","S_HINDUTONE"]),{
 def:cfg=>({input:"Janma Nakshatra",direction:"bride row / groom column",scale:"qualifies / does not qualify",rule:"Qualifies when the Tradition A Yoni matrix gives at least "+(cfg.yoniMin||2)+" of 4. "+DERIVED_NOTE}),
 calc(b,g,cfg){const s=labRow(b,g,"Yoni",false).score,ok=s>=(cfg.yoniMin||2);return Q(this,b,g,cfg,ok,`Tradition A Yoni score ${s}/4 (${nk(b.nak).yoni} bride, ${nk(g.nak).yoni} groom). ${DERIVED_NOTE}`)}}));
addK(Object.assign(BASE("rasi","bhakoot","Rasi (Porutham)","राशि","Moon Rashi","symmetric (provisional mapping)",7,["S_COURSE","S_HINDUTONE"]),{
 def:()=>({input:"Moon Rashi",direction:"symmetric (provisional mapping)",scale:"qualifies / does not qualify",rule:"Provisional course mapping: qualifies when the Rashi pair is 1/1, 3/11, 4/10 or 7/7 (same classes as Bhakoot). A verified Tamil Rasi rule is NOT established (open research item; whether 2/12, 5/9 and 6/8 are treated alike is unverified)."}),
 calc(b,g,cfg){const k=fwd2(b.rashi,g.rashi),ok=[1,3,4,7,10,11].includes(k[0]);return Q(this,b,g,cfg,ok,`Rashi counts ${k[0]}/${k[1]}. Provisional mapping (Level 7): coincides with Bhakoot by construction.`)}}));
const fwd2=(a,b)=>[mod(b-a,12)+1,mod(a-b,12)+1];
addK(Object.assign(BASE("rasyadhipathi","maitri","Rasyadhipathi","राश्यधिपति","Moon-sign lords","both viewpoints",7,["S_COURSE","S_HINDUTONE"]),{
 def:cfg=>({input:"Moon-sign lords",direction:"both viewpoints",scale:"qualifies / does not qualify",rule:"Qualifies when the Graha Maitri score is at least "+(cfg.maitriMin||3)+" of 5 (same lord, or neither lord regards the other as an enemy). "+DERIVED_NOTE}),
 calc(b,g,cfg){const r=labRow(b,g,"Graha Maitri",false),ok=r.score>=(cfg.maitriMin||3);return Q(this,b,g,cfg,ok,`Graha Maitri score ${r.score}/5. ${r.exp} ${DERIVED_NOTE}`)}}));
addK(Object.assign(BASE("vasya","vashya","Vasya (Porutham)","वश्य","Moon Rashi group","bride row / groom column",7,["S_COURSE","S_HINDUTONE"]),{
 def:cfg=>({input:"Moon Rashi group",direction:"bride row / groom column",scale:"qualifies / does not qualify",rule:"Qualifies when the Tradition A Vashya matrix gives at least "+(cfg.vasyaMin||1)+" of 2. "+DERIVED_NOTE}),
 calc(b,g,cfg){const r=labRow(b,g,"Vashya",false),ok=r.score>=(cfg.vasyaMin||1);return Q(this,b,g,cfg,ok,`Tradition A Vashya score ${r.score}/2. ${DERIVED_NOTE} (Sagittarius and Capricorn are classed by the Pada midpoint here.)`)}}));
addK(Object.assign(BASE("rajju_t","rajju","Rajju (Porutham)","रज्जु","Janma Nakshatra","symmetric",5,["S_COURSE","S_HINDUBLOG"]),{
 def:()=>({input:"Janma Nakshatra",direction:"symmetric",scale:"qualifies / does not qualify",rule:"Qualifies when the two Rajju groups differ (same group = Rajju Dosha). Many Tamil sources call Rajju essential; this is a priority statement, not a score."}),
 calc(b,g,cfg){const x=nk(b.nak).rajju,y=nk(g.nak).rajju,ok=x!==y;return Q(this,b,g,cfg,ok,`${x} and ${y} Rajju. ${ok?"Different groups.":"Same group: Rajju Dosha."}`,{dosha:!ok})}}));
addK(Object.assign(BASE("vedha_t","vedha","Vedhai (Porutham)","वेध","Janma Nakshatra","symmetric pair list",5,["S_COURSE","S_HINDUTONE"]),{
 def:()=>({input:"Janma Nakshatra",direction:"symmetric pair list",scale:"qualifies / does not qualify",rule:"Qualifies when the two Nakshatras are not a listed Vedha pair. The pair list comes from the course file (14 commonly listed pairs, grade C; Dhanishta appears with both Chitra and Mrigashira) and is not verified."}),
 calc(b,g,cfg){const bn=nk(b.nak).name,gn=nk(g.nak).name,v=D().vedha.pairs.some(p=>(p[0]===bn&&p[1]===gn)||(p[0]===gn&&p[1]===bn));return Q(this,b,g,cfg,!v,v?`${bn} and ${gn} are a listed Vedha pair.`:"Not a listed Vedha pair.",{dosha:v})}}));
/* ---- chart-based factors: input-based only (the app has no planetary positions beyond the Moon) ---- */
const CHOVVA_VARIANTS={
 K1:{id:"K1",label:"Houses 1, 7, 8 from Lagna (one Malayalam-language summary; reading of the summary is itself an assumption)",refs:["lagna"],houses:[1,7,8],evidence:7,sources:["S_ONLINEJ_ML"]},
 K2:{id:"K2",label:"Houses 1, 2, 4, 7, 8, 12 from Lagna, Moon and Venus (one uploaded document; unknown authorship)",refs:["lagna","moon","venus"],houses:[1,2,4,7,8,12],evidence:7,sources:["S_SCRIBD_HM"]}};
function chovvaPerson(inp,variantId){
 const v=CHOVVA_VARIANTS[variantId];if(!v)throw new TE("UNSUPPORTED_VARIANT","Unknown Chovva variant "+variantId);
 if(!inp)throw new TE("MISSING_CHART_INPUT","Mars house positions are required (the app does not calculate planets other than the Moon).");
 const hits=[];let supplied=0;
 v.refs.forEach(r=>{const h=inp[r];if(h===undefined||h===null||h==="")return;supplied++;if(!Number.isInteger(h)||h<1||h>12)throw new TE("INVALID_HOUSE","House must be 1 to 12.");if(v.houses.includes(h))hits.push(`Mars in house ${h} from ${r}`)});
 if(!supplied)throw new TE("MISSING_CHART_INPUT","No Mars house supplied for the references required by variant "+variantId);
 return {present:hits.length>0,hits,supplied};
}
function chovvaCompare(a,b,variantId){
 const x=chovvaPerson(a,variantId),y=chovvaPerson(b,variantId);
 const st=x.present&&y.present?"BOTH_PRESENT":x.present||y.present?"ONE_SIDED":"NEITHER";
 return {variant:variantId,a:x,b:y,status:st,note:"Whether a balance of both charts cancels or reduces the Dosha is source-specific and is NOT applied here. No numerical Papasamyam value is calculated (no verified method).",evidence:7};
}
addK({id:"chovva_k",concept:"chovva",name:"Chovva Dosham (input-based)",hi:"चोव्वा दोषम्",kind:"chart",input:"Mars house positions supplied by the user",directional:false,evidence:7,sources:["S_ONLINEJ_ML","S_SCRIBD_HM","S_ROXY"],
 def:cfg=>({input:"Mars houses (user-supplied)",direction:"symmetric",scale:"present / absent per chart",rule:(CHOVVA_VARIANTS[cfg.chovva||"K1"]).label}),
 calc(b,g,cfg){if(!cfg.chart)return res(this,b,g,{cfg,raw:null,max:null,status:"INPUT_REQUIRED",label:"Input required",detail:"Supply Mars house positions for both charts."});
  const c=chovvaCompare(cfg.chart.bride,cfg.chart.groom,cfg.chovva||"K1");return res(this,b,g,{cfg,raw:null,max:null,status:c.status,label:c.status.replace(/_/g," ").toLowerCase(),detail:`Bride: ${c.a.present?c.a.hits.join("; "):"no qualifying Mars house"}. Groom: ${c.b.present?c.b.hits.join("; "):"no qualifying Mars house"}. ${c.note}`,chovva:c})}});
