const IMPLEMENTED=()=>Object.values(PROFILES).filter(p=>p.koota&&p.status!=="PARTIAL_INPUT_BASED");
const Registry={
 list:()=>Object.values(PROFILES),
 get(id){const p=PROFILES[id];if(!p)throw new TE("UNKNOWN_PROFILE","Unsupported tradition/profile: "+id);return p},
 kootasOf(id){const p=Registry.get(id);if(!p.koota)throw new TE("NO_KOOTA_LIST",id+" has no verified Koota list ("+p.status+").");return p.koota.slice()},
 implemented:()=>IMPLEMENTED().map(p=>p.id),
 versions:()=>Object.values(PROFILES).map(p=>({id:p.id,version:p.version,status:p.status}))
};
function validateProfile(p){
 if(p.scoring&&p.scoring.type==="weighted"&&p.scoring.thresholds)throw new TE("CONFLICTING_SCORING","A profile cannot be both weighted and count-based.");
 (p.koota||[]).forEach(k=>{if(!KOOTAS[k])throw new TE("MISSING_CLASSIFICATION","No Koota plug-in for "+k)});
 if(!p.sources||(!p.sources.length&&p.koota))throw new TE("MISSING_SOURCE","Profile "+p.id+" has no source record.");
 p.sources.forEach(s=>{if(!SOURCES[s])throw new TE("MISSING_SOURCE_RECORD","Unknown source id "+s)});
 return true;
}

/* ===================== ScoringProfileEngine ===================== */
const Scoring={
 score(profile,results,opts){
  opts=opts||{};const s=profile.scoring;if(!s)return {type:"none"};
  if(s.type==="weighted"||s.type==="weighted+passdosha"){
   const sc=results.filter(r=>r.kind==="score"),total=sc.reduce((a,r)=>a+r.raw,0);
   const doshas=results.filter(r=>r.dosha).map(r=>r.name);
   return {type:s.type,rawTotal:total,max:s.max,doshas,note:s.note+" The total never cancels a flagged Dosha."};
  }
  if(s.type==="count"){
   const q=results.filter(r=>r.qualifies).length,out={type:"count",qualifyingCount:q,of:results.length,thresholds:s.thresholds.map(t=>({n:t.n,met:q>=t.n,note:t.note})),weights:s.weights};
   if(s.mandatoryOption){const f=s.mandatoryOption.filter(id=>{const r=results.find(x=>x.kootaId===id);return r&&!r.qualifies});out.mandatoryCheck={factors:s.mandatoryOption,failed:f,passed:f.length===0,note:s.mandatoryNote}}
   out.failedFactors=results.filter(r=>!r.qualifies).map(r=>r.name);
   return out;
  }
  if(s.type==="qualitative")return {type:"qualitative",note:s.note};
  throw new TE("CONFLICTING_SCORING","Unknown scoring type "+s.type);
 },
 convert(){return {status:"NOT_SUPPORTED",reason:"No verified or justified model converts a 36-point Ashtakoota total into a ten-Porutham count, or the reverse. Different factor lists, scales and weights are not interchangeable."}}
};

/* ===================== ExceptionRuleEngine ===================== */
const EXC=[
 {id:"NADI_SAME_RASHI_DIFF_NAKSHATRA",koota:"nadi",tradition:"Ashtakoota",rule:"Same Rashi, different Nakshatra: mentioned in some manuals as an exception to Nadi Dosha",evidence:7,status:"UNVERIFIED",effect:"cancellation claimed by some manuals; verse and scope unverified",test:(b,g)=>b.rashi===g.rashi&&b.nak!==g.nak,needs:"nadi"},
 {id:"NADI_SAME_NAKSHATRA_DIFF_RASHI",koota:"nadi",tradition:"Ashtakoota",rule:"Same Nakshatra, different Rashi (split Nakshatra): attributed in modern sources to Muhurta Chintamani",evidence:7,status:"UNVERIFIED",effect:"cancellation claimed; verse numbering and scope unverified",test:(b,g)=>b.nak===g.nak&&b.rashi!==g.rashi,needs:"nadi"},
 {id:"NADI_SAME_NAKSHATRA_DIFF_PADA",koota:"nadi",tradition:"Ashtakoota",rule:"Same Nakshatra, different Pada: differing opinions; scope unverified",evidence:7,status:"UNVERIFIED",effect:"disputed",test:(b,g)=>b.nak===g.nak&&b.pada!==g.pada,needs:"nadi"},
 {id:"NADI_FRIENDLY_RASHI_LORDS",koota:"nadi",tradition:"Ashtakoota (regional)",rule:"Same or mutually friendly Moon-sign lords: mentioned as mitigating in some regional rules",evidence:7,status:"UNVERIFIED",effect:"mitigation claimed",test:(b,g)=>{const x=LORD[b.rashi],y=LORD[g.rashi];return x===y||(att(x,y)==="F"&&att(y,x)==="F")},needs:"nadi"},
 {id:"BHAKOOT_SAME_OR_FRIENDLY_LORD",koota:"bhakoot",tradition:"Ashtakoota",rule:"Same Moon-sign lord, or mutual friends: exception categories mentioned in some manuals",evidence:7,status:"UNVERIFIED",effect:"cancellation claimed; source unverified",test:(b,g)=>{const x=LORD[b.rashi],y=LORD[g.rashi];return x===y||(att(x,y)==="F"&&att(y,x)==="F")},needs:"bhakoot"},
 {id:"GANA_SUPPORTIVE_FACTORS",koota:"gana",tradition:"Ashtakoota",rule:"Favourable Rashi lords or Navamsha support: categories mentioned in some manuals (a separate chart layer)",evidence:7,status:"UNVERIFIED",effect:"mitigation claimed",test:()=>true,needs:"gana"},
 {id:"RAJJU_REGIONAL_RELAXATION",koota:"rajju",tradition:"Regional (unspecified)",rule:"Regional relaxation rules for Rajju exist in some manuals; none is attached",evidence:7,status:"PENDING_RESEARCH",effect:"unknown",test:()=>true,needs:"rajju"},
 {id:"VEDHA_REGIONAL_RELAXATION",koota:"vedha",tradition:"Regional (unspecified)",rule:"Regional relaxation rules for Vedha exist in some manuals; none is attached",evidence:7,status:"PENDING_RESEARCH",effect:"unknown",test:()=>true,needs:"vedha"},
 {id:"KERALA_CHOVVA_BALANCE",koota:"chovva",tradition:"Kerala (source-specific)",rule:"Presence of the Dosha in both charts is described as balancing in some sources; method not verified",evidence:7,status:"PENDING_RESEARCH",effect:"unknown",test:()=>true,needs:"chovva"}
];
function att(a,b){return LE().PROFILES&&lab0(a,b)}
const NAT={Sun:{F:["Moon","Mars","Jupiter"],E:["Venus","Saturn"]},Moon:{F:["Sun","Mercury"],E:[]},Mars:{F:["Sun","Moon","Jupiter"],E:["Mercury"]},Mercury:{F:["Sun","Venus"],E:["Moon"]},Jupiter:{F:["Sun","Moon","Mars"],E:["Mercury","Venus"]},Venus:{F:["Mercury","Saturn"],E:["Sun","Moon"]},Saturn:{F:["Mercury","Venus"],E:["Sun","Moon","Mars"]}};
function lab0(a,b){return NAT[a].F.includes(b)?"F":NAT[a].E.includes(b)?"E":"N"}
const Exceptions={
 list:()=>EXC.map(e=>({id:e.id,koota:e.koota,tradition:e.tradition,rule:e.rule,evidenceLevel:e.evidence,evidence:EVID[e.evidence],status:e.status,effect:e.effect})),
 candidates(b,g,kootaResults){
  const doshaKoota=new Set(kootaResults.filter(r=>r.dosha||(r.kind==="score"&&r.raw===0)).map(r=>r.concept));
  return EXC.filter(e=>doshaKoota.has(e.needs)&&e.test(b,g)).map(e=>({id:e.id,koota:e.koota,tradition:e.tradition,rule:e.rule,evidenceLevel:e.evidence,status:e.status,applied:false,reason:"Candidate only. Not applied unless explicitly activated with acknowledgement."}));
 },
 /* activation must be explicit; an unverified rule needs acknowledgeUnverified:true; the raw result is never overwritten */
 apply(b,g,kootaResults,opts){
  opts=opts||{};const act=opts.activate||[],cand=Exceptions.candidates(b,g,kootaResults),applied=[];
  act.forEach(id=>{
   const e=EXC.find(x=>x.id===id);if(!e)throw new TE("UNSUPPORTED_EXCEPTION","Unknown exception "+id);
   if(e.status==="PENDING_RESEARCH")throw new TE("INCOMPLETE_EXCEPTION_DATA","Exception "+id+" has no documented rule data and cannot be activated.");
   if(e.evidence>=6&&!opts.acknowledgeUnverified)throw new TE("UNVERIFIED_EXCEPTION","Exception "+id+" is unverified (Level "+e.evidence+"); explicit acknowledgement is required.");
   if(!cand.some(c=>c.id===id)){applied.push({id,applied:false,reason:"Conditions not met for this pair."});return}
   applied.push({id,applied:true,effect:e.effect,evidenceLevel:e.evidence,note:"Applied by explicit user choice; the raw result is unchanged and the exception is labelled unverified."});
  });
  const raw=kootaResults.filter(r=>r.kind==="score").reduce((a,r)=>a+r.raw,0);
  return {candidates:cand,applied,rawTotal:raw,adjustedTotal:null,note:"No score is restored by the engine; any restoration would need a profile that defines it."};
 }
};

/* ===================== KootaCalculationEngine ===================== */
const Calc={
 run(profileId,bride,groom,opts){
  opts=opts||{};const p=Registry.get(profileId);
  if(p.status==="PENDING_RESEARCH"||p.status==="IMPLEMENTATION_NOT_VERIFIED"||p.status==="META")
   return {profileId,status:p.status,message:p.note,kootas:[],scoring:{type:"none"},sources:p.sources,scoreConversion:"NOT_SUPPORTED"};
  validateProfile(p);
  const cfg=Object.assign({},p.cfg,opts.cfg||{});
  if(opts.chart)cfg.chart=opts.chart;
  let ks=p.koota.map(id=>KOOTAS[id].calc(bride,groom,cfg));
  const sc=Scoring.score(p,ks,opts);
  const ex=Exceptions.apply(bride,groom,ks,opts);
  return {profileId,status:p.status==="IMPLEMENTED"?"CALCULATED":p.status,kootas:ks,scoring:sc,exceptions:ex,sources:p.sources,evidence:p.evidence,version:p.version,scoreConversion:"NOT_SUPPORTED",bride:{name:bride.name,pada:bride.pada,rashi:bride.rashiName},groom:{name:groom.name,pada:groom.pada,rashi:groom.rashiName}};
 }
};

/* ===================== ComparativeMatchingEngine ===================== */
function label(r){return r?r.label:"not in this profile"}
const Comparative={
 compare(bride,groom,profileIds,opts){
  opts=opts||{};if(!profileIds||!profileIds.length)throw new TE("NO_PROFILE","Select at least one profile.");
  const runs=profileIds.map(id=>Calc.run(id,bride,groom,opts));
  const rows=CONCEPTS.map(c=>{
   const cells=runs.map(r=>{const k=r.kootas.find(x=>x.concept===c.id);return {profileId:r.profileId,result:k||null,text:r.status==="PENDING_RESEARCH"||r.status==="IMPLEMENTATION_NOT_VERIFIED"?"pending research":label(k)}});
   const present=cells.filter(x=>x.result);
   const byKind={};present.forEach(x=>{(byKind[x.result.kind]=byKind[x.result.kind]||[]).push(x.text)});
   const diff=Object.values(byKind).some(a=>a.length>1&&new Set(a).size>1),scaleDiff=Object.keys(byKind).length>1;
   const listDiff=present.length>0&&present.length<cells.filter(x=>x.text!=="pending research").length;
   return {concept:c,cells,differs:diff,scaleDiffers:scaleDiff,listDifference:listDiff,why:diff||listDiff||scaleDiff?Comparative.why(c,cells):[]};
  });
  return {bride:{name:bride.name,pada:bride.pada,rashi:bride.rashiName},groom:{name:groom.name,pada:groom.pada,rashi:groom.rashiName},runs,rows,scoreConversion:"NOT_SUPPORTED",overall:"PROFILE_BASED_COMPARISON",note:"No combined score is produced."};
 },
 why(concept,cells){
  const out=[],have=cells.filter(c=>c.result),seen=new Set();
  for(let i=0;i<have.length;i++)for(let j=i+1;j<have.length;j++){
   const a=have[i],b=have[j],ka=KOOTAS[a.result.kootaId],kb=KOOTAS[b.result.kootaId];
   if(!ka||!kb)continue;const pa=Registry.get(a.profileId),pb=Registry.get(b.profileId);
   const da=ka.def(Object.assign({},pa.cfg,{})),db=kb.def(Object.assign({},pb.cfg,{}));
   const key=ka.id+"|"+kb.id+"|"+da.rule+"|"+db.rule;if(seen.has(key))continue;seen.add(key);
   const bits=[];
   if(ka.kind!==kb.kind)bits.push(`different scale (${da.scale} versus ${db.scale}): results are not comparable as numbers`);
   if(da.input!==db.input)bits.push(`different input (${da.input} versus ${db.input})`);
   if(da.rule!==db.rule&&ka.kind===kb.kind)bits.push(`different rule text (profile data differs): "${da.rule}" versus "${db.rule}"`);
   if(da.direction!==db.direction)bits.push(`different orientation (${da.direction} versus ${db.direction})`);
   if(!bits.length&&a.text!==b.text)bits.push("same rule statement; difference comes from the other data tables used");
   if(bits.length)out.push({a:a.profileId,b:b.profileId,reasons:bits});
  }
  return out;
 },
 listDifferences(profileIds){
  const sets=profileIds.map(id=>({id,list:(Registry.get(id).koota||[]).map(k=>KOOTAS[k].concept)}));
  return sets.map(s=>({id:s.id,onlyHere:s.list.filter(c=>sets.some(o=>o!==s&&!o.list.includes(c)))}));
 }
};

/* ===================== MatchingReportEngine ===================== */
const Report={
 build(bride,groom,profileIds,opts){
  opts=opts||{};const cmp=Comparative.compare(bride,groom,profileIds,opts);
  const secB=cmp.runs.map(r=>{const p=Registry.get(r.profileId);return {profile:p.id,name:p.name,status:r.status,version:p.version,sources:p.sources.map(s=>SOURCES[s]),kootaList:p.koota,evidenceLevel:EVID[p.evidence]}});
  const secC=cmp.runs.map(r=>({profile:r.profileId,status:r.status,kootas:r.kootas.map(k=>({name:k.name,result:k.label,detail:k.detail,evidence:EVID[k.evidence],directional:k.directional})),scoring:r.scoring,exceptions:r.exceptions?{candidates:r.exceptions.candidates.map(c=>c.id),applied:r.exceptions.applied}:null,message:r.message||""}));
  const diffs=cmp.rows.filter(x=>x.differs||x.listDifference||x.scaleDiffers).map(x=>({koota:x.concept.name,cells:x.cells.map(c=>({profile:c.profileId,text:c.text})),why:x.why}));
  const common=cmp.rows.filter(x=>!x.differs&&!x.listDifference&&!x.scaleDiffers&&x.cells.filter(c=>c.result).length>1).map(x=>x.concept.name);
  return {
   A:{ayanamsha:opts.ayanamsha||"Not applicable: Nakshatra and Pada were entered directly",birthData:opts.birthData||"not supplied",person:cmp.bride,role:"bride (first person)"},
   B:{person:cmp.groom,role:"groom (second person)"},
   selectedTraditions:secB,individualResults:secC,comparison:{commonResults:common,differences:diffs,listDifferences:Comparative.listDifferences(profileIds.filter(id=>Registry.get(id).koota)),scoreConversion:"NOT_SUPPORTED"},
   interpretation:"Results differ because the profiles use different factor lists, scales, thresholds, orientations and data tables. A higher number or more qualifying factors in one profile does not make that tradition superior. Differences are listed rule by rule above.",
   disclaimer:DISCLAIMER
  };
 },
 text(rep){
  const L=[];L.push("ASTROSUTRAS multi-tradition comparison report");
  L.push(`Bride: ${rep.A.person.name} Pada ${rep.A.person.pada} (${rep.A.person.rashi}). Groom: ${rep.B.person.name} Pada ${rep.B.person.pada} (${rep.B.person.rashi}).`);
  L.push("Calculation settings: "+rep.A.ayanamsha+".");
  rep.individualResults.forEach(r=>{L.push("");L.push(`== ${r.profile} [${r.status}] ==`);if(r.message)L.push(r.message);r.kootas.forEach(k=>L.push(`- ${k.name}: ${k.result}. ${k.detail}`));
   if(r.scoring&&r.scoring.type==="weighted+passdosha"||r.scoring&&r.scoring.type==="weighted")L.push(`Weighted total (this profile only): ${r.scoring.rawTotal} of ${r.scoring.max}. Doshas flagged: ${r.scoring.doshas.join(", ")||"none"}.`);
   if(r.scoring&&r.scoring.type==="count"){L.push(`Qualifying Poruthams (this profile only): ${r.scoring.qualifyingCount} of ${r.scoring.of}. ${r.scoring.thresholds.map(t=>">="+t.n+": "+(t.met?"met":"not met")).join("; ")}.`);if(r.scoring.mandatoryCheck)L.push(`Rajju and Vedhai both qualify: ${r.scoring.mandatoryCheck.passed?"yes":"no"} (optional priority check, not a score).`)}});
  L.push("");L.push("== Where the profiles differ ==");rep.comparison.differences.forEach(d=>L.push(`- ${d.koota}: ${d.cells.map(c=>c.profile+" = "+c.text).join(" | ")}`+(d.why.length?" Why: "+d.why.map(w=>w.reasons.join("; ")).join(" / "):"")));
  L.push("");L.push("Score conversion between systems: NOT_SUPPORTED.");L.push(rep.interpretation);L.push("");L.push(rep.disclaimer);return L.join("\n");
 }
};

/* ===================== matrices, directional counting ===================== */
const Matrix={
 count27(kind,cfg){ // kind: dina | mahendra | sd ; rows bride, columns groom
  cfg=cfg||TAMIL_CFG;const m=[];for(let i=0;i<27;i++){const r=[];for(let j=0;j<27;j++){const c=fwd(i,j);r.push({count:c,ok:kind==="dina"?dinaOK(c,cfg):kind==="mahendra"?[4,7,10,13,16,19,22,25].includes(c):sdOK(c,cfg)})}m.push(r)}return m},
 rajju27(){const m=[];for(let i=0;i<27;i++){const r=[];for(let j=0;j<27;j++)r.push(nk(i).rajju===nk(j).rajju);m.push(r)}return m},
 directional(){return [
  ["Dina","bride's Nakshatra","groom's Nakshatra","forward, inclusive, remainder after 9","reverse not used in the commonly cited statement","S_HINDUTONE"],
  ["Mahendra","bride's Nakshatra","groom's Nakshatra","forward, inclusive","not specified in sources found","S_VEDICBIRTH_M"],
  ["Stree Deergha","bride's Nakshatra","groom's Nakshatra","forward, inclusive","not used; a symmetric formula must not replace the directional rule","S_VEDICBIRTH_S"],
  ["Tara (Ashtakoota)","each person in turn","the other person","both directions, remainder after 9","yes: both directions are read","S_COURSE"],
  ["Gana","bride (row)","groom (column)","matrix lookup, not a count","not applicable (matrix is directional)","S_COURSE"],
  ["Yoni","bride (row)","groom (column)","matrix lookup (Profile A not symmetric)","not applicable","S_COURSE"],
  ["Rajju","both Nakshatras","-","group comparison","symmetric in the course profile","S_COURSE"],
  ["Vedha","both Nakshatras","-","pair list","symmetric list","S_COURSE"]]}
};

