/* ===================== master matrix, inclusion matrix, cases ===================== */
function masterRows(){
 const rows=[];
 ["NORTH_INDIAN_ASHTAKOOTA_BASE","TRADITION_A_ASHTAKOOTA_RAJJU_VEDHA","TAMIL_PATHU_PORUTHAM_PROFILE_A"].forEach(pid=>{
  const p=PROFILES[pid];p.koota.forEach(kid=>{
   if(pid==="TRADITION_A_ASHTAKOOTA_RAJJU_VEDHA"&&!["rajju","vedha"].includes(kid))return;
   const k=KOOTAS[kid],d=k.def(p.cfg||{});
   rows.push({tradition:p.name,profile:pid,koota:k.name,alt:CONCEPTS.find(c=>c.id===k.concept).name,source:k.sources.join(", "),input:d.input,reference:d.direction,classification:k.kind==="qualify"?"Derived or published threshold":"Course table",counting:/count|bride to groom/.test(d.direction)?d.direction:"not a counting factor",formula:["dina","mahendra","stree_deergha","tara"].includes(kid)?"count = ((end - start + 27) MOD 27) + 1":"table / matrix lookup",max:k.max===undefined||k.max===null?"-":String(k.max),qualifying:d.rule,unfavourable:k.kind==="qualify"?"Does not qualify (not a Dosha unless stated)":k.kind==="passdosha"?"Dosha":"Lower score",exceptions:"Candidates listed in the exception comparison; none applied automatically",cancellation:"Unverified (Level 7) where claimed",directional:k.directional?"Directional":"Symmetric",regional:"Variants exist; see Different Schools",evidence:EVID[k.evidence],software:"Implemented here; other software not verified"});
  });
 });
 ["TELUGU_DASHAKOOTA_PROFILE_A","KANNADA_DASHAKOOTA_PROFILE_A","KERALA_ANUKULYA_PROFILE_A"].forEach(pid=>{
  const p=PROFILES[pid];TAMIL_KOOTAS.forEach(kid=>{const k=KOOTAS[kid];rows.push({tradition:p.name,profile:pid,koota:k.name,alt:"-",source:"none identified",input:"PENDING_RESEARCH",reference:"PENDING_RESEARCH",classification:"PENDING_RESEARCH",counting:"PENDING_RESEARCH",formula:"PENDING_RESEARCH",max:"PENDING_RESEARCH",qualifying:"PENDING_RESEARCH",unfavourable:"PENDING_RESEARCH",exceptions:"PENDING_RESEARCH",cancellation:"PENDING_RESEARCH",directional:"PENDING_RESEARCH",regional:"PENDING_RESEARCH",evidence:EVID[7],software:"not verified"})})});
 ["K1","K2"].forEach(v=>{const c=CHOVVA_VARIANTS[v];rows.push({tradition:"Kerala Chovva check, variant "+v,profile:"KERALA_PAPASAMYAM_PROFILE_A",koota:"Chovva Dosham",alt:"Kuja Dosha",source:c.sources.join(", "),input:"Mars houses (user supplied)",reference:c.refs.join(", "),classification:"Houses "+c.houses.join(", "),counting:"house counted from reference",formula:"Mars house in set",max:"-",qualifying:"Not present",unfavourable:"Present",exceptions:"PENDING_RESEARCH",cancellation:"PENDING_RESEARCH",directional:"Symmetric",regional:"Variants disagree",evidence:EVID[c.evidence],software:"Input-based checker only"})});
 return rows;
}
const INCL=(()=>{const N="Not normally included",A="Additional assessment",S="Standard inclusion",V="Not verified",SS="Source-specific";
 const m={varna:[S,N,V,V,V,V],vashya:[S,S,V,V,SS,V],tara:[S,S,V,V,SS,V],yoni:[S,S,V,V,SS,V],maitri:[S,S,V,V,SS,V],gana:[S,S,V,V,SS,V],bhakoot:[S,S,V,V,SS,V],nadi:[S,N,V,V,V,V],mahendra:[N,S,V,V,SS,V],stree_deergha:[N,S,V,V,SS,V],rajju:[A,S,V,V,SS,V],vedha:[A,S,V,V,SS,V],papasamyam:[V,SS,V,V,A,V],chovva:[A,A,V,V,A,V]};
 return {systems:["North Indian Ashtakoota","Tamil Pathu Porutham","Telugu","Kannada","Kerala","Other"],rows:CONCEPTS.map(c=>({concept:c,cells:m[c.id]}))}})();
const EVIDENCE_NOTE="Status values describe what the sources found by this course say; 'Not normally included' is not 'forbidden', and 'Not verified' means the course found no independent documentation.";

/* ---- 25 cases: pairs are SEARCHED by the engine, never typed by hand ---- */
const CASE_SPECS=[
 {n:1,cat:"High Ashtakoota total and few qualifying Poruthams",find:s=>s.ash>=26&&s.t.q<=5},
 {n:2,cat:"Low Ashtakoota total and many qualifying Poruthams",find:s=>s.ash<=17&&s.t.q>=8},
 {n:3,cat:"Nadi Dosha in Ashtakoota; the Tamil list has no Nadi factor",find:s=>s.nadi0&&s.t.q>=7},
 {n:4,cat:"Rajju Dosha under the Tamil profile while the Ashtakoota total is at least 18",find:s=>s.rajjuSame&&s.ash>=18},
 {n:5,cat:"Mahendra qualifies but Stree Deergha does not",find:s=>s.q.mahendra&&!s.q.stree_deergha},
 {n:6,cat:"Dina qualifies but Rajju does not",find:s=>s.q.tara&&!s.q.rajju},
 {n:7,cat:"Rajju qualifies but Vedhai does not: impossible in the course data (every listed Vedha pair shares a Rajju group); a Vedhai pair is shown instead",find:s=>!s.q.rajju&&!s.q.vedha,doc:"In the course data every listed Vedha pair also belongs to one Rajju group, so 'Rajju favourable but Vedha adverse' cannot occur. Published lists may differ; this is recorded as an open research item. The pair shown fails both."},
 {n:8,cat:"Rasi qualifies but Rasyadhipathi does not",find:s=>s.q.bhakoot&&!s.q.maitri},
 {n:9,cat:"Gana qualifies but Yoni does not",find:s=>s.q.gana&&!s.q.yoni},
 {n:10,cat:"A different result because the orientation (bride and groom) is reversed",find:s=>s.swapDiff},
 {n:11,cat:"A different result because of a threshold (Stree Deergha > 13 versus >= 7)",find:s=>s.sdThresholdDiff},
 {n:12,cat:"Nadi Dosha with candidate exceptions listed (unverified; none applied)",find:s=>s.nadi0&&s.candNadi>0},
 {n:13,cat:"Rajju table: only one table exists in the course data",find:s=>s.rajjuSame,doc:"The course holds one Rajju table. A second documented table was not found, so no difference can be shown. The case records a same-Rajju pair and states the gap."},
 {n:14,cat:"A different result because of a Yoni table (Profile A versus earlier symmetric table A0)",find:s=>s.yoniTableDiff},
 {n:15,cat:"A different result because of Vashya scoring (Profile A versus earlier table A0)",find:s=>s.vashyaTableDiff},
 {n:16,cat:"Nadi: candidate cancellation (unverified) against the Tamil profile which has no Nadi",find:s=>s.nadi0&&s.candNadi>0&&s.t.q>=6},
 {n:17,cat:"Bhakoot Dosha with a same or friendly lord candidate exception",find:s=>s.bhak0&&s.candBhak>0},
 {n:18,cat:"Papasamyam: illustrative chart inputs",find:s=>true,chart:{bride:{lagna:7,moon:3,venus:9},groom:{lagna:1,moon:5,venus:2}},doc:"Papasamyam has no verified calculation method here. Illustrative Mars houses are used only for the Chovva comparison."},
 {n:19,cat:"Chovva Dosham: the two variants disagree",find:s=>true,chart:{bride:{lagna:2,moon:6,venus:10},groom:{lagna:5,moon:9,venus:11}},variants:true,doc:"Illustrative Mars houses supplied by the course. Variant K1 uses house 1, 7, 8 from Lagna; K2 uses 1, 2, 4, 7, 8, 12 from Lagna, Moon and Venus."},
 {n:20,cat:"Same Nakshatra, different Pada",find:s=>s.sameNak&&s.diffPada},
 {n:21,cat:"Same Rashi, different Nakshatra",find:s=>s.sameRashi&&!s.sameNak},
 {n:22,cat:"Same Nakshatra, different Rashi (split Nakshatra)",find:s=>s.sameNak&&!s.sameRashi},
 {n:23,cat:"Adverse Koota matching; individual chart strength is a separate layer (discussion case)",find:s=>s.ash<=17,discussion:true},
 {n:24,cat:"Favourable Koota matching; individual chart concerns are a separate layer (discussion case)",find:s=>s.ash>=30,discussion:true},
 {n:25,cat:"Two families following different traditions read the same pair",find:s=>s.ash<18&&s.t.q>=7}
];
const _persons=[];
function persons(){if(!_persons.length)allPersons().forEach(p=>_persons.push(p));return _persons}
function snapshot(b,g){
 const L=lab(b,g,true),row=n=>L.rows.find(r=>r.name===n);
 const t=Calc.run("TAMIL_PATHU_PORUTHAM_PROFILE_A",b,g),q={};t.kootas.forEach(k=>{q[k.concept]=k.qualifies});
 const sw=Calc.run("TAMIL_PATHU_PORUTHAM_PROFILE_A",g,b),swapDiff=sw.kootas.some((k,i)=>k.qualifies!==t.kootas.find(x=>x.concept===k.concept).qualifies&&["tara","mahendra","stree_deergha","gana","yoni","vashya"].includes(k.concept));
 const c=fwd(b.nak,g.nak);
 const nadi0=row("Nadi").score===0,bhak0=row("Bhakoot").score===0;
 const kr=L.rows.map(r=>({concept:r.name==="Graha Maitri"?"maitri":r.name.toLowerCase(),dosha:r.dosha,kind:r.score===null?"passdosha":"score",raw:r.score}));
 return {ash:L.rows.filter(r=>r.score!==null).reduce((a,r)=>a+r.score,0),t:{q:t.scoring.qualifyingCount},q,swapDiff,nadi0,bhak0,
  rajjuSame:row("Rajju").dosha,sameNak:b.nak===g.nak,sameRashi:b.rashi===g.rashi,diffPada:b.pada!==g.pada,
  sdThresholdDiff:c>=7&&c<=13,
  candNadi:nadi0?Exceptions.candidates(b,g,kr.map(k=>Object.assign({},k,{concept:k.concept==="nadi"?"nadi":k.concept}))).filter(e=>e.koota==="nadi").length:0,
  candBhak:bhak0?Exceptions.candidates(b,g,kr).filter(e=>e.koota==="bhakoot").length:0,
  yoniTableDiff:labRow(b,g,"Yoni",false).score!==LE().calc(LE().PROFILES.A_y0,b,g).rows.find(r=>r.name==="Yoni").score,
  vashyaTableDiff:labRow(b,g,"Vashya",false).score!==LE().calc(LE().PROFILES.A_v0,b,g).rows.find(r=>r.name==="Vashya").score};
}
let _cases=null;
function cases(){
 if(_cases)return _cases;const P=persons(),used=new Set(),out=[];
 CASE_SPECS.forEach(sp=>{
  let found=null;const first=P.filter(p=>p.pada===1),base=(sp.n>=20&&sp.n<=22)?P:first,k=(sp.n*5)%base.length,pool=base.slice(k).concat(base.slice(0,k));
  outer:for(const b of pool)for(const g of base){
   if(sp.n<20&&b.nak===g.nak)continue;
   const key=b.nak+"-"+b.pada+"-"+g.nak+"-"+g.pada;if(used.has(key)&&(sp.n<20||sp.n>=23)&&sp.n!==13)continue;
   let s;try{s=snapshot(b,g)}catch(e){continue}
   if(sp.find(s)){found={b,g,s,key};break outer}
  }
  if(found)used.add(found.key);
  out.push({n:sp.n,category:sp.cat,doc:sp.doc||"",discussion:!!sp.discussion,chart:sp.chart||null,variants:!!sp.variants,bride:found&&found.b,groom:found&&found.g,found:!!found});
 });
 _cases=out;return out;
}
function runCase(c,profileIds){
 profileIds=profileIds||["NORTH_INDIAN_ASHTAKOOTA_BASE","TRADITION_A_ASHTAKOOTA_RAJJU_VEDHA","TAMIL_PATHU_PORUTHAM_PROFILE_A"];
 return Comparative.compare(c.bride,c.groom,profileIds,{});
}

