function rulesFor(koota){return RULES.filter(r=>r.dosha_type===koota)}
function noneStatement(koota){return rulesFor(koota).length?null:NONE_STATEMENT}
const ENUM={cancellation_type:["COMPLETE","PARTIAL","MITIGATION","DISPUTED"],condition_logic:["ALL","ANY","CUSTOM"],evidence_class:["A","B","C","D","E","F"],verification_status:["VERIFIED","PARTIALLY_VERIFIED","UNVERIFIED"]};
function validateRule(r){const bad=[];
  ["rule_id","dosha_type","rule_name","tradition","source_reference","evidence_class","conditions","condition_logic","cancellation_type","score_restoration","limitations","verification_status"].forEach(f=>{if(r[f]===undefined)bad.push("missing "+f)});
  Object.keys(ENUM).forEach(k=>{if(r[k]!==undefined&&!ENUM[k].includes(r[k]))bad.push("bad "+k+": "+r[k])});
  if(typeof r.score_restoration!=="boolean")bad.push("score_restoration must be boolean");
  if(!Array.isArray(r.conditions)||!r.conditions.length)bad.push("conditions empty");
  else r.conditions.forEach(c=>{if(!COND[c.key])bad.push("unknown condition "+c.key)});
  return bad}
