/* ---------- STAGE 3: severity (an educational framework, not a classical scale) ---------- */
const SEVERITY_LEVELS=[
 {level:0,name:"No Dosha identified",criteria:"No Koota is flagged and no scored Koota is below its maximum."},
 {level:1,name:"Minor score deficiency",criteria:"No Dosha flag, but at least one scored Koota is below its maximum."},
 {level:2,name:"Recognised but limited Dosha",criteria:"One Dosha flag, isolated (no other Koota scores zero), or all flagged Doshas limited by an applied mitigation."},
 {level:3,name:"Dosha with additional supporting concerns",criteria:"One unresolved Dosha together with at least one other Koota scoring zero, or two Doshas that overlap on one underlying relationship."},
 {level:4,name:"Multiple independent unfavourable indications",criteria:"Two unresolved Doshas that are independent (different basis or different classification)."},
 {level:5,name:"Serious unresolved concern under the selected tradition",criteria:"Three or more independent unresolved Doshas, or an unresolved Dosha that the selected tradition treats as a veto (set by the practitioner)."}];
const NOTE_SEV="These levels are a proposed educational and software framework. They are not an ancient classical scale and carry no numerical weights.";
const unresolvedSet=["IDENTIFIED_NOT_APPLIED","DISPUTED_CANCELLATION","CONFLICT_REVIEW_REQUIRED","UNRESOLVED"];
function independence(names){
  const out=[],basis=n=>KOOTA[n].basis;
  for(let i=0;i<names.length;i++)for(let j=i+1;j<names.length;j++){
    const a=names[i],b=names[j],ov=OVERLAP.find(o=>(o[0]===a&&o[1]===b)||(o[0]===b&&o[1]===a));
    let relation,text;
    if(ov){relation="OVERLAPPING";text=ov[2]}
    else if(basis(a)===basis(b)){relation="SAME_INPUT_DIFFERENT_TABLE";text=`Both read the ${basis(a)} data, but through different classification tables: the same two inputs are being re-read, not independently confirmed.`}
    else{relation="INDEPENDENT";text="Different inputs (Rashi versus Nakshatra) and different classifications."}
    out.push({a,b,relation,text})}
  return out}
function severity(cls,evaluation,opts){
  opts=opts||{};const veto=opts.veto||[],doshas=cls.records.filter(r=>r.doshaFlag),
    zeroOthers=n=>cls.records.filter(r=>r.raw===0&&r.koota!==n&&!r.doshaFlag).length;
  const level=(unres,limited)=>{
    const all=unres.concat(limited);
    if(!all.length)return cls.records.some(r=>r.deficiency)?1:0;
    if(unres.some(r=>veto.includes(r.koota)))return 5;
    const ind=independence(unres.map(r=>r.koota)).filter(p=>p.relation==="INDEPENDENT"||p.relation==="SAME_INPUT_DIFFERENT_TABLE").length;
    const ov=independence(unres.map(r=>r.koota)).some(p=>p.relation==="OVERLAPPING");
    if(unres.length>=3&&!ov)return 5;
    if(unres.length>=3)return 4;
    if(unres.length===2)return ov?3:4;
    if(unres.length===1)return zeroOthers(unres[0].koota)>0?3:2;
    return 2};
  const before=level(doshas,[]);
  let after=before;
  if(evaluation){
    const st=n=>(evaluation.byKoota[n]||{}).adjustedStatus;
    const unres=doshas.filter(r=>unresolvedSet.includes(st(r.koota)||"IDENTIFIED_NOT_APPLIED"));
    const limited=doshas.filter(r=>["MITIGATED","PARTIALLY_CANCELLED"].includes(st(r.koota)));
    after=level(unres,limited)}
  return {before,after,beforeName:SEVERITY_LEVELS[before].name,afterName:SEVERITY_LEVELS[after].name,criteria:SEVERITY_LEVELS[after].criteria,note:NOTE_SEV,
    record:{severityBeforeExceptions:before,severityAfterExceptions:after,remainingConcerns:[],evidenceSupporting:[],confidenceInSource:"Low: all rules are unverified (class E or F)"}}}

/* ---------- STAGE 4: exception and cancellation examination ---------- */
function collapse(applied){const seen={},out=[];applied.forEach(r=>{const k=r.dupGroup||r.rule_id;if(!seen[k]){seen[k]=1;out.push(r)}});return out}
function resolve(applied){
  if(!applied.length)return "IDENTIFIED_NOT_APPLIED";
  const t=applied.map(r=>r.cancellation_type);
  if(t.includes("COMPLETE")&&t.includes("DISPUTED"))return "CONFLICT_REVIEW_REQUIRED";
  if(t.includes("COMPLETE"))return "CANCELLED_UNDER_SELECTED_PROFILE";
  if(t.includes("DISPUTED"))return "DISPUTED_CANCELLATION";
  if(t.includes("PARTIAL"))return "PARTIALLY_CANCELLED";
  return "MITIGATED"}
function evalRule(rule,ctx,prof,cfg,doshaRec){
  const conds=rule.conditions.map(c=>Object.assign({id:c.key,desc:c.desc,kind:c.kind},COND[c.key](ctx)));
  const met=rule.condition_logic==="ANY"?conds.some(x=>x.s==="MET"):conds.every(x=>x.s==="MET");
  const anyNot=conds.some(x=>x.s==="NOT_MET"),anyUnk=conds.some(x=>x.s==="UNKNOWN");
  let verdict=met?"CONDITIONS_MET":(rule.condition_logic==="ANY"?(anyUnk?"UNKNOWN_INPUT":"CONDITIONS_NOT_MET"):(anyNot?"CONDITIONS_NOT_MET":"UNKNOWN_INPUT"));
  const enabled=prof.enabled.includes(rule.rule_id),needAck=rule.verification_status!=="VERIFIED";
  let applied=false,blocked=null;
  if(verdict==="CONDITIONS_MET"){
    if(prof.research)blocked="Research profile: candidates are shown, none is applied.";
    else if(!enabled)blocked="Not enabled in the selected cancellation profile.";
    else if(needAck&&!cfg.acknowledgeUnverified)blocked="Unverified rule: not applied until the practitioner acknowledges that it is unverified.";
    else if((prof.requireNadiFor||[]).includes(rule.dosha_type)&&rule.dosha_type!=="Nadi"){
      const pre=COND.nadiAbsent(ctx);
      if(pre.s==="MET")applied=true;else blocked="Prerequisite not met: the selected profile requires Nadi Dosha to be absent ("+pre.d+").";}
    else applied=true}
  return {rule_id:rule.rule_id,rule_name:rule.rule_name,dosha_type:rule.dosha_type,evidence_class:rule.evidence_class,verification_status:rule.verification_status,cancellation_type:rule.cancellation_type,tradition:rule.tradition,
    logic:rule.condition_logic,conditions:conds,verdict,enabled,applied,blockedReason:applied?null:(verdict==="CONDITIONS_MET"?blocked:(verdict==="UNKNOWN_INPUT"?"A required input is missing (see the conditions marked UNKNOWN).":"Required condition(s) not satisfied.")),
    limitations:rule.limitations,urls:rule.urls,scope:rule.scope,dupGroup:rule.dupGroup||null,restorable:rule.cancellation_type==="COMPLETE"}}
function evaluateCancellation(cls,cfg){
  if(!cls||cls.stage<2)throw err("STAGE_SKIPPED","Cancellation can only be examined after identification and classification (stages 1 and 2). A Dosha cannot jump straight to cancellation.");
  cfg=cfg||{};const prof=PROFILES[cfg.profile||"T0"];if(!prof)throw err("UNKNOWN_CANCEL_PROFILE","Unknown cancellation profile: "+cfg.profile);
  const ctx=ctxOf(cls,cfg.declared),byKoota={},warnings=[];
  cls.records.forEach(r=>{
    if(!r.doshaFlag){byKoota[r.koota]={koota:r.koota,rawScore:r.raw,rawStatus:r.status,adjustedStatus:"NOT_EVALUATED",examined:[],applied:[],restored:false,adjustedScore:null,statement:"No Dosha flag: nothing to examine.",originalPreserved:true};return}
    const rules=rulesFor(r.koota);
    if(!rules.length){byKoota[r.koota]={koota:r.koota,rawScore:r.raw,rawStatus:"DOSHA_PRESENT",adjustedStatus:"IDENTIFIED_NOT_APPLIED",examined:[],applied:[],restored:false,adjustedScore:null,statement:NONE_STATEMENT,originalPreserved:true};return}
    const ex=rules.map(rule=>evalRule(rule,ctx,prof,cfg,r)),ap=collapse(ex.filter(x=>x.applied));
    const status=resolve(ap),restoreIds=ap.filter(x=>prof.restore.includes(x.rule_id));
    let restored=false,adj=null;
    restoreIds.forEach(x=>{if(!x.restorable)warnings.push(`${x.rule_id}: restoration requested by the profile but the rule is not a complete cancellation, so no points are restored.`)});
    if(restoreIds.some(x=>x.restorable)&&r.max!==null){restored=true;adj=r.max}
    byKoota[r.koota]={koota:r.koota,rawScore:r.raw,max:r.max,rawStatus:"DOSHA_PRESENT",adjustedStatus:status,examined:ex,applied:ap.map(x=>x.rule_id),restored,adjustedScore:adj,
      statement:status==="IDENTIFIED_NOT_APPLIED"?"Dosha identified; no rule applied. "+(ex.some(x=>x.verdict==="CONDITIONS_MET")?"At least one candidate rule's conditions are met but it was not applied (see reasons).":"No candidate rule's conditions are met."):"Status changed under the selected profile by: "+ap.map(x=>x.rule_id).join(", ")+". The raw score is unchanged.",originalPreserved:true,
      remaining:status==="CANCELLED_UNDER_SELECTED_PROFILE"?["Cancellation is profile-specific and rests on an unverified rule."]:["Dosha not removed: examine the complete horoscope before concluding."]}});
  const restoredPts=Object.values(byKoota).reduce((s,x)=>s+(x.restored?(x.adjustedScore-x.rawScore):0),0);
  return Object.assign({},cls,{stage:4,stageName:"EXCEPTIONS_EXAMINED",cancelProfile:prof.id,cancelProfileName:prof.name,acknowledgeUnverified:!!cfg.acknowledgeUnverified,byKoota,warnings,
    rawTotal:cls.rawTotal,adjustedTotal:restoredPts?cls.rawTotal+restoredPts:null,adjustedLabel:restoredPts?"ADJUSTED total (points restored by an explicitly enabled rule); raw total shown separately":null,scoreRestoredPoints:restoredPts})}

/* ---------- multiple Doshas, interaction matrix, double counting ---------- */
const INTER=["Nadi","Bhakoot","Gana","Yoni","Rajju","Vedha","Tara","Graha Maitri"];
function interactionMatrix(){
  return INTER.map(a=>INTER.map(b=>{
    if(a===b)return {a,b,self:true,text:"–"};
    const cands=RULES.filter(r=>r.dosha_type===a&&r.conditions.some(c=>c.ref===b));
    if(!cands.length)return {a,b,text:"No established automatic cancellation",candidates:[]};
    return {a,b,text:"Candidate only (unverified): "+cands.map(x=>x.rule_id+" ["+x.evidence_class+", "+x.cancellation_type+"]").join("; "),candidates:cands.map(x=>({rule_id:x.rule_id,grade:x.evidence_class,type:x.cancellation_type,logic:x.condition_logic}))}}))}
function multiple(ev){
  const act=ev.records.filter(r=>r.doshaFlag),names=act.map(r=>r.koota),rel=independence(names);
  const unres=act.filter(r=>unresolvedSet.includes((ev.byKoota[r.koota]||{}).adjustedStatus||"IDENTIFIED_NOT_APPLIED"));
  const warnings=[];rel.forEach(p=>{if(p.relation==="OVERLAPPING")warnings.push(`${p.a} and ${p.b} overlap: ${p.text}. Counting both as separate Doshas would double-count one relationship.`);if(p.relation==="SAME_INPUT_DIFFERENT_TABLE")warnings.push(`${p.a} and ${p.b}: ${p.text}`)});
  const independentPairs=rel.filter(p=>p.relation==="INDEPENDENT").length;
  let pattern;
  if(names.length===0)pattern="No Dosha";else if(names.length===1)pattern="One isolated Dosha";else if(rel.some(p=>p.relation==="OVERLAPPING"))pattern=`${names.length} Doshas, at least two arising from one underlying relationship`;else pattern=`${names.length} Doshas from different classifications`;
  return {doshas:names,count:names.length,unresolvedCount:unres.length,relations:rel,independentPairs,warnings,pattern,
    effectiveIndependentCount:names.length-rel.filter(p=>p.relation==="OVERLAPPING").length,
    notes:["No Dosha cancels another unless an identifiable source says so (see the interaction matrix).","A high total does not cancel any Dosha.","Do not add Dosha 'severities': no source supplies weights."]}}

/* ---------- STAGE 5: synthesis ---------- */
const FINAL_CATS=["Favourable under the selected tradition","Generally supportive with minor qualifications","Mixed results requiring detailed review","Significant unresolved concerns under the selected tradition","Inconclusive due to missing or uncertain birth data","Different traditions produce different conclusions"];
function finalCategory(o){
  if(o.uncertain)return FINAL_CATS[4];
  if(o.traditionsDiffer)return FINAL_CATS[5];
  if(o.severityAfter>=4)return FINAL_CATS[3];
  if(o.severityAfter===3||o.unresolved>=1&&o.severityAfter>=2)return FINAL_CATS[2];
  if(o.severityAfter===2||o.severityAfter===1)return FINAL_CATS[1];
  return FINAL_CATS[0]}
const DECISION=[
 {agg:"High",dosha:"None",cancel:"Not applicable",horo:"Supportive",concl:"Explain favourable findings"},
 {agg:"High",dosha:"Present",cancel:"Uncancelled",horo:"Supportive",concl:"Explain unresolved Dosha"},
 {agg:"High",dosha:"Present",cancel:"Cancelled",horo:"Supportive",concl:"Explain source-specific cancellation"},
 {agg:"Low",dosha:"None",cancel:"Not applicable",horo:"Supportive",concl:"Explain score limitations"},
 {agg:"Low",dosha:"Present",cancel:"Partially mitigated",horo:"Mixed",concl:"Explain remaining concerns"},
 {agg:"Low",dosha:"Multiple",cancel:"Uncancelled",horo:"Mixed",concl:"Recommend detailed traditional review"},
 {agg:"Moderate",dosha:"Present",cancel:"Disputed",horo:"Supportive",concl:"Present school-specific conclusions"},
 {agg:"High",dosha:"Multiple",cancel:"Uncancelled",horo:"Mixed",concl:"Explain that the total does not hide the unresolved Doshas; detailed review"},
 {agg:"Moderate",dosha:"None",cancel:"Not applicable",horo:"Mixed",concl:"Explain that the Koota layer is quiet and the chart layer needs its own examination"},
 {agg:"Any",dosha:"Any",cancel:"Any",horo:"Birth time uncertain",concl:"Report as inconclusive; state which results depend on the birth time"}];
const BANDS="Descriptive bands for this exercise only (not a pass/fail threshold): Low = below 18 of 36, Moderate = 18 to 27.5, High = 28 or more.";
function band(total){return total<18?"Low":total<28?"Moderate":"High"}

/* ---------- horoscope verification (practitioner-entered; the app calculates only the Moon) ---------- */
const HORO=[
 ["Lagna and Lagna lord","Individual chart","Basis of the chart; needs exact birth time and place."],
 ["Moon and Moon sign","Individual chart","Computed by this app from the Moon longitude; the only planet it calculates."],
 ["Seventh house and seventh lord","Individual chart","Traditional house of partnership; read with its aspects and conjunctions."],
 ["Venus","Individual chart","Natural significator in many schools; interpretation depends on the school."],
 ["Jupiter","Individual chart","Natural significator in many schools; interpretation depends on the school."],
 ["Planetary dignity and relevant aspects","Individual chart","Strength judgements differ between schools."],
 ["Navamsha (D-9): Lagna, Lagna lord, 7th house and lord, Venus, Jupiter","Divisional chart","Supportive context; not a cancellation of any Koota Dosha."],
 ["Dasha: current Mahadasha and Antardasha","Timing context","Timing context only; never alters a Koota score."],
 ["Moon–Moon and Moon-sign relationship","Mutual chart","Already captured in Koota layer; do not count twice."],
 ["Venus–Mars relationship across charts","Mutual chart","Method-dependent supplementary analysis."],
 ["Seventh-house connections across charts","Mutual chart","Method-dependent supplementary analysis."],
 ["Navamsha relationships across charts","Mutual chart","Supportive context."]].map(x=>({factor:x[0],layer:x[1],limit:x[2]}));
function horoscopeSummary(entries){
  entries=entries||{};const items=HORO.map((h,i)=>({factor:h.factor,layer:h.layer,note:entries[i]||"",entered:!!(entries[i]&&String(entries[i]).trim())}));
  return {items,entered:items.filter(x=>x.entered).length,total:items.length,statement:"Chart observations are practitioner-entered. They are reported in a separate layer and never rewrite the Koota score or the Dosha record."}}

/* ---------- manual override ---------- */
const Override={
  create(o){const need=["koota","rule_id","reason","source","note","date"];need.forEach(f=>{if(!o||o[f]===undefined||o[f]===null||String(o[f]).trim()==="")throw err("OVERRIDE_INCOMPLETE","Manual override needs: "+need.join(", ")+". Missing: "+f+".")});
    return {koota:o.koota,rule_id:o.rule_id,declaredStatus:o.declaredStatus||"PRACTITIONER_DECLARED_CANCELLED",reason:o.reason,source:o.source,note:o.note,date:o.date,systemResultRetained:true}},
  apply(analysis,overrides){const copy=JSON.parse(JSON.stringify(analysis));copy.overrides=(overrides||[]).map(o=>Object.assign({},o,{originalSystemStatus:(copy.byKoota[o.koota]||{}).adjustedStatus||null,originalRawScore:(copy.byKoota[o.koota]||{}).rawScore}));
    copy.overridesNote="Practitioner overrides are shown beside the original system result. They never overwrite it.";return copy}};

/* ---------- audit trail ---------- */
const Audit={
  freeze(analysis,meta){const rec=JSON.parse(JSON.stringify(analysis));rec.audit={rulebookVersion:VERSION,sourceRegisterVersion:SOURCE_REGISTER_VERSION,calculationProfile:analysis.profile,cancelProfile:analysis.cancelProfile,savedOn:(meta&&meta.date)||new Date().toISOString().slice(0,10),
    ruleVersions:RULES.map(r=>r.rule_id+"@"+VERSION)};return rec},
  verify(frozen,currentVersion){const cv=currentVersion||VERSION;return {sameVersion:frozen.audit&&frozen.audit.rulebookVersion===cv,savedVersion:frozen.audit&&frozen.audit.rulebookVersion,currentVersion:cv,note:frozen.audit&&frozen.audit.rulebookVersion===cv?"Stored report was generated with the current rulebook.":"Stored report keeps its original result; it was generated with an earlier rulebook version and has not been silently recalculated."}}};

