  /* --- calculation: D-9 --- */
  const d9=L=>Divisional.d9Sign(L);
  ok("D-9: Aries 0° = Aries",d9(0)===0);
  ok("D-9: Aries 3°20' = Taurus",d9(3.3333334)===1);
  ok("D-9: Aries 29°59' = Sagittarius",d9(29.99)===8);
  ok("D-9: Taurus 0° (30°) = Capricorn (fixed sign starts from the 9th)",d9(30)===9);
  ok("D-9: Gemini 0° (60°) = Libra (dual sign starts from the 5th)",d9(60)===6);
  ok("D-9: Cancer 0° (90°) = Cancer",d9(90)===3);
  ok("D-9: Pisces 29°59' = Pisces",d9(359.99)===11);
  let agree=true,n360=0;for(let i=0;i<360;i++){const L=i+0.37;n360++;if(Divisional.d9ByRule(L)!==d9(L)){agree=false;break}}
  ok("D-9: movable/fixed/dual start rule agrees with floor(L/3°20') mod 12 for 360 longitudes",agree&&n360===360);
  if(e){let same=true;for(let i=0;i<360;i++){const L=i*1.0+0.123,a=locate(L),b=e.identify(L);if(a.sign!==b.rashi||a.nak!==b.nak||a.pada!==b.pada||a.nav!==b.nav){same=false;break}}ok("locate() agrees with LabUI identify() for 360 longitudes (sign, Nakshatra, Pada, D-9)",same);
    const bd=[13.333333333,13.3333333,26.6666666667,119.99999,120,359.9999];let sb=true;bd.forEach(L=>{const a=locate(L),b=e.identify(L);if(a.nak!==b.nak||a.pada!==b.pada||a.nav!==b.nav)sb=false});ok("locate() agrees with identify() at Nakshatra/Pada/Rashi boundary values",sb)}
  else ok("LabUI available for cross-checks",false,"not loaded");
  ok("Locate wraps 360° to 0°",locate(360).sign===0&&locate(360).pada===1);
  /* --- chart build --- */
  const base={name:"T",longitudes:{Lagna:ab(0,10),Sun:ab(6,5),Moon:ab(3,15),Mars:ab(9,20),Mercury:ab(5,18),Jupiter:ab(8,12),Venus:ab(7,3),Saturn:ab(10,25),Rahu:ab(2,20)},retro:{Saturn:true}};
  const c=mk(base);
  ok("Chart builds without errors",c.errors.length===0,c.errors.join("; "));
  ok("Ketu derived as Rahu + 180°",Math.abs(c.planets.Ketu.L-norm(c.planets.Rahu.L+180))<1e-9&&c.status.planets.Ketu==="DERIVED");
  ok("Whole-sign houses: Aries Lagna puts Libra Sun in house 7",c.planets.Sun.house===7);
  ok("House 1 is the Lagna sign, house 12 is Pisces for Aries Lagna",c.houses[0].sign===0&&c.houses[11].sign===11);
  ok("Seventh lord for Aries Lagna is Venus",Lords.of(c,7)==="Venus");
  ok("Houses lorded by Mars for Aries Lagna are 1 and 8",JSON.stringify(Lords.housesOf(c,"Mars"))==="[1,8]");
  /* --- validation and missing data --- */
  const bad=Natal.build({ayanamsha:"",longitudes:{}});ok("Missing ayanamsha is an error",bad.errors.length>0);
  const noEph=Natal.build({ayanamsha:"Lahiri (Chitra Paksha)",longitudes:{Sun:10}});ok("Missing ephemeris source is an error",noEph.errors.some(x=>/ephemeris/i.test(x)));
  ok("Unsupported house system is rejected",Natal.build(Object.assign({},base,{ayanamsha:"Lahiri (Chitra Paksha)",ephemerisSource:"x",houseSystem:"PLACIDUS"})).errors.some(x=>/PLACIDUS/.test(x)));
  ok("Invalid longitude text is rejected",!Birth.parseLongitude("abc").ok&&!Birth.parseLongitude(400).ok&&!Birth.parseLongitude({sign:"Aries",deg:31}).ok);
  ok("Longitude text 'Taurus 10:30' reads as 40.5°",Math.abs(Birth.parseLongitude("Taurus 10:30").L-40.5)<1e-9);
  const unk=mk(Object.assign({},base,{timeAccuracy:"unknown"}));
  ok("Unknown birth time: Lagna and houses are UNAVAILABLE, not guessed",unk.lagna===null&&unk.houses===null&&unk.status.lagna==="UNAVAILABLE"&&unk.planets.Sun.house===null);
  ok("Unknown birth time: Moon Nakshatra is still available",unk.planets.Moon.nakName==="Pushya");
  ok("Unknown birth time: interpretation says Lagna-dependent output is unavailable",Interpretation.observe(unk,"PARASHARI_GRAHA").every(x=>x.layer==="reliability"));
  ok("Unknown birth time: functional nature UNAVAILABLE",Lords.functional(unk,"Mars").status==="UNAVAILABLE");
