  if(e){const mo=Natal.build({ayanamsha:"Lahiri (Chitra Paksha)",moonOnly:true,date:"1992-04-12",time:"00:00",tzOffset:0,longitudes:{}});ok("Moon-only mode computes the Moon and leaves other planets NOT_COMPUTED",mo.status.planets.Moon==="COMPUTED_MOON"&&mo.status.planets.Sun==="NOT_COMPUTED"&&mo.lagna===null)}
