  const lag=LE().identify(L.Lagna),lagSign=lag.rashi,retro=sch.retro||[];
  const bodies={};
  [...BODIES].forEach(p=>{
    const id=LE().identify(L[p]),house=houseOf(id.rashi,lagSign),dig=dignityOf(p,id.rashi,id.degIn);
    bodies[p]={name:p,L:L[p],sign:id.rashi,signName:SIGNS[id.rashi],degIn:id.degIn,nak:id.nak,nakName:DT().nakshatra[id.nak].name,pada:id.pada,house,nav:id.nav,navName:SIGNS[id.nav],
      retro:retro.includes(p)&&p!=="Rahu"&&p!=="Ketu",dignity:dig,vargottama:id.rashi===id.nav,lordOf:ownedHouses(p,lagSign),moon:p==="Moon",schematic:p!=="Moon"};
  });
  const sunL=L.Sun;
  BODIES.forEach(p=>{const b=bodies[p];if(COMB[p]){const orb=b.retro?COMB[p].r:COMB[p].o,d=angDist(L[p],sunL);b.combust=d<orb;b.sunDistance=d;b.combustOrb=orb}else b.combust=false});
  const houses=Array.from({length:12},(_,i)=>{const sign=mod(lagSign+i,12);return {house:i+1,sign,signName:SIGNS[sign],lord:LORD[sign],occupants:BODIES.filter(p=>bodies[p].house===i+1)}});
  // aspects
  BODIES.forEach(p=>{const b=bodies[p];b.aspectsHouses=(asp.map[p]||[]).map(k=>mod(b.house-1+k-1,12)+1)});
  houses.forEach(h=>{h.aspectedBy=BODIES.filter(p=>bodies[p].aspectsHouses.includes(h.house)&&bodies[p].house!==h.house)});
  // D-9
  const navLag=lag.nav,d9={lagnaSign:navLag,lagnaName:SIGNS[navLag],lagnaLord:LORD[navLag],bodies:{}};
  BODIES.forEach(p=>{const ns=bodies[p].nav;d9.bodies[p]={sign:ns,signName:SIGNS[ns],house:houseOf(ns,navLag),dignity:dignityBySign(p,ns)}});
  d9.houses=Array.from({length:12},(_,i)=>{const sign=mod(navLag+i,12);return {house:i+1,sign,signName:SIGNS[sign],lord:LORD[sign],occupants:BODIES.filter(p=>d9.bodies[p].house===i+1)}});
  const seventhSign=mod(lagSign+6,12),seventhLord=LORD[seventhSign];
