  const kar=["Sun","Moon","Mars","Mercury","Jupiter","Venus","Saturn"].map(p=>({p,d:bodies[p].degIn})).sort((a,b)=>b.d-a.d);
  const names7=["Atmakaraka","Amatyakaraka","Bhratrikaraka","Matrikaraka","Putrakaraka","Gnatikaraka","Darakaraka"];
  const karakas=kar.map((x,i)=>({planet:x.p,degIn:x.d,karaka:names7[i]}));
  return {aspectSystem:asp,lagna:{L:L.Lagna,sign:lagSign,signName:SIGNS[lagSign],degIn:lag.degIn,lord:LORD[lagSign],schematic:true,nav:lag.nav},bodies,houses,d9,seventhSign,seventhSignName:SIGNS[seventhSign],seventhLord,karakas,darakaraka:karakas[6].planet,
    sameDegreeWarning:new Set(kar.map(x=>Math.round(x.d*1000))).size<7,positionsNote:SCHEMATIC_NOTE+" for every body except the Moon."};
