  const b=te.personFromLongitude(bp.moon.L),g=te.personFromLongitude(gp.moon.L),out={available:true,profiles:[]};
  const tam=te.Calc.run("TAMIL_PATHU_PORUTHAM_PROFILE_A",b,g);
  out.tamil={status:tam.status,count:tam.scoring.qualifyingCount,of:tam.scoring.of,thresholds:tam.scoring.thresholds,failed:tam.scoring.failedFactors,mandatory:tam.scoring.mandatoryCheck,
    rows:tam.kootas.map(k=>({name:k.name,qualifies:k.qualifies,label:k.label,detail:k.detail||""})),version:tam.version,note:"Provisional course profile; the ten-factor list is documented by contemporary websites (Level 5/6); thresholds for several factors are derived from course tables (Level 7). No score conversion to 36 points is supported."};
  ["TELUGU_DASHAKOOTA_PROFILE_A","KANNADA_DASHAKOOTA_PROFILE_A","KERALA_ANUKULYA_PROFILE_A","OTHER_REGIONAL_PROFILES"].forEach(id=>{const p=te.Registry.get(id);out.profiles.push({id,name:p.name,status:p.status,note:p.note})});
