  const rows=(a,cols)=>`<table><tr>${cols.map(c=>`<th>${esc(c[0])}</th>`).join("")}</tr>${a.map(r=>`<tr>${cols.map(c=>`<td>${esc(c[1](r))}</td>`).join("")}</tr>`).join("")}</table>`;
  const obsList=o=>o&&o.available?"<ul>"+o.items.map(i=>`<li><b>${esc(i.topic||i.id)}</b>${i.polarity?" ["+esc(i.polarity)+"]":""}: ${esc(i.text)}</li>`).join("")+"</ul>":"<p>Not available (positions not entered).</p>";
