const STATUSES=["Draft","Birth Data Pending","Calculation Pending","Calculation Verified","Koota Analysis Complete","Horoscope Analysis Complete","Practitioner Review Pending","Report Draft","Report Approved","Report Issued","Archived"];
function transition(from,to){
  const i=STATUSES.indexOf(from),j=STATUSES.indexOf(to);
  if(i<0||j<0)throw new PE("UNKNOWN_STATUS","Unknown case status.");
  if(from==="Archived")throw new PE("ARCHIVED","An archived case cannot change status.");
  if(to==="Archived")return {ok:true,note:"Archiving is allowed from any state; the record is kept."};
  if(j===i+1)return {ok:true,note:"Forward step."};
  if(j<i&&from==="Report Issued")return {ok:true,newVersion:true,note:"A change after issue creates a new report version; the issued report is never altered."};
  if(j<i&&j>=1)return {ok:true,note:"Return to an earlier stage for correction."};
  throw new PE("INVALID_TRANSITION",`${from} → ${to} skips a stage. Move one step at a time.`);
}
