const arc=L=>({q:`Sidereal Moon ${dm(L)}: convert to arc-minutes M, then find Nakshatra number, Pada and Rashi.`,a:()=>{const p=E.identify(L),M=Math.round(L*60*100)/100;return `M = ${M}'; Nakshatra ${p.nak+1} (${D.nakshatra[p.nak].name}); Pada ${p.pada}; ${SIGNS[p.rashi]}`}});
const koota=(k,b,g)=>({q:`${pair(b,g)}: ${k} score?`,a:()=>{const r=row(R(b,g),k);return `${r.score} of ${r.max}. ${r.exp}`}});
const dosha=(k,b,g)=>({q:`${pair(b,g)}: is ${k} Dosha present?`,a:()=>{const r=row(R(b,g),k);return `${r.dosha?"Yes":"No"}. ${r.exp}`}});
const full=(b,g)=>({q:`${pair(b,g)}: all eight Koota scores, total, Rajju and Vedha, and every Dosha.`,a:()=>{const res=R(b,g);return res.rows.filter(r=>r.score!==null).map(r=>`${r.name} ${r.score}`).join(", ")+`; total ${res.total}/36; Rajju ${row(res,"Rajju").cls}; Vedha ${row(res,"Vedha").cls}; Doshas: ${res.rows.filter(r=>r.dosha).map(r=>r.name).join(", ")||"none"}`}});
