const CH=[{k:"A",L:43+20/60,txt:"43°20'",rashi:1,rl:"Venus",nak:3,pada:2,nl:"Moon"},{k:"B",L:100.5,txt:"100°30'",rashi:3,rl:"Moon",nak:7,pada:3,nl:"Saturn"}];
function steps(c){const M=Math.round(c.L*60),r=Math.floor(M/1800),n=Math.floor(M/800),rem=M%800,pd=Math.floor(rem/200)+1,NK=D().nakshatra;
  return `<ol><li>Convert to arc-minutes: M = ${Math.floor(c.L)}×60 + ${M%60} = <b>${M}'</b>.</li><li>Rashi: ${M} ÷ 1800 = ${(M/1800).toFixed(3)}, floor ${r}, so Rashi number ${r+1} = <b>${SIGNS[r]}</b>; its lord is <b>${LORD[r]}</b>.</li><li>Nakshatra: ${M} ÷ 800 = ${(M/800).toFixed(3)}, floor ${n}, so Nakshatra number ${n+1} = <b>${NK[n].name}</b>.</li><li>Pada: ${M} mod 800 = ${rem}; ${rem} ÷ 200 = ${(rem/200).toFixed(3)}, floor ${pd-1}, so Pada <b>${pd}</b>.</li><li>Nakshatra lord (Vimshottari order, index (${n+1} − 1) mod 9 = ${n%9}): <b>${NK[n].lord}</b>.</li></ol>`}
function workshop(){
  const NK=D().nakshatra,saved=store.get("ws1",{}),opt=(arr,sel)=>`<option value="">—</option>`+arr.map(a=>`<option>${a}</option>`).join("");
  return `<p class="tag">Illustrative longitudes for teaching only; they are not real birth records. Identify everything, check, then open the guided calculation. Do not score Dashkoot on Day 1.</p>
  <div class="grid" style="grid-template-columns:repeat(auto-fit,minmax(300px,1fr))">${CH.map(c=>`<div class="card" data-chart="${c.k}"><h3>Sample Chart ${c.k}: Moon at ${c.txt} sidereal</h3>
  <label class="row"><span>Moon sign (Rashi)</span><select data-f="rashi">${opt(SIGNS)}</select></label>
  <label class="row"><span>Rashi lord</span><select data-f="rl">${opt(["Sun","Moon","Mars","Mercury","Jupiter","Venus","Saturn"])}</select></label>
  <label class="row"><span>Nakshatra</span><select data-f="nak">${opt(NK.map(n=>n.name))}</select></label>
  <label class="row"><span>Pada</span><select data-f="pada">${opt([1,2,3,4])}</select></label>
  <label class="row"><span>Nakshatra lord</span><select data-f="nl">${opt(["Ketu","Venus","Sun","Moon","Mars","Rahu","Jupiter","Saturn","Mercury"])}</select></label>
  <p><button data-wx="wscheck" data-c="${c.k}">Check my answers</button> <button data-wx="wsshow" data-c="${c.k}">Show guided calculation</button></p><div class="wsres"></div></div>`).join("")}</div>
  <div class="card" style="margin-top:12px"><h3>Compare the two charts (no scoring)</h3><ol><li>Compare the Moon signs: Taurus (2nd) and Cancer (4th). Counting inclusively both ways gives 3 and 11; this is the Bhakoot idea that Day 8 will name and score.</li><li>Compare the Nakshatras: Rohini (4th) and Pushya (8th). Counting inclusively both ways gives 5 and 24 (they add to 29); Day 4 explains what this does.</li><li>Why are the two comparisons different? Rashi compares 30° signs; Nakshatra compares 13°20' stars. Both come from the same longitude.</li><li>Information needed later: both Rashis and lords, both Nakshatras with Padas, longitude confidence and the ayanamsha.</li></ol>
  <div class="note"><b>Common mistakes.</b> Dividing degrees by 13 instead of 13°20'. Counting Pada from 0 instead of 1. Treating 43°20' as Pada 1: it is exactly the start of Pada 2 (one arc-second earlier it is Pada 1). Mixing tropical and sidereal longitude. Confusing the Nakshatra lord with the Rashi lord.</div>
  <div class="note"><b>Audit note.</b> The supplied illustrative value 113°10' lies in Ashlesha Pada 2 (lord Mercury), not Pushya Pada 3; Chart B uses 100°30', which is Pushya Pada 3 as intended.</div></div>`;
}
function wsCheck(k,root){
  const c=CH.find(x=>x.k===k),NK=D().nakshatra,card=root,get=f=>card.querySelector(`[data-f=${f}]`).value;
  const exp={rashi:SIGNS[c.rashi],rl:c.rl,nak:NK[c.nak].name,pada:String(c.pada),nl:c.nl};let ok=0;const msgs=[];
  Object.keys(exp).forEach(f=>{const g=get(f),good=g===exp[f];if(good)ok++;card.querySelector(`[data-f=${f}]`).style.borderColor=good?"var(--ok)":"var(--bad)";if(!good)msgs.push(f)});
  const res=card.querySelector(".wsres");res.innerHTML=`<div class="note"><b>${ok} of 5 correct.</b> ${ok===5?"Well done.":"Review the highlighted fields and open the guided calculation."}</div>`;
  if(ok===5){const s=store.get("ws1",{});s[k]=true;store.set("ws1",s)}
}
