const CDEF={sel:"C01",who:"A",asp:"P1",yd:365.25,date:"",src:"case",cid:""};
function userCases(){return store.get("p14cases",{list:[]}).list}
function chartSource(S){
  const P=PX();
  if(S.src==="case"){if(!unlocked("chart",S.sel))return {locked:true,id:S.sel};return {r:P.Case.compute(S.sel,{aspect:S.asp,yearDays:Number(S.yd)}),id:S.sel}}
  const u=userCases().find(x=>x.id===S.cid);if(!u)return {none:true};
  return {r:P.Case.compute(u.def,{aspect:S.asp,yearDays:Number(S.yd)}),id:u.id,user:true};
}
function caseChooser(S){
  const uc=userCases();
  return `<div class="card"><p><label>Source <select data-k="src"><option value="case" ${S.src==="case"?"selected":""}>Teaching case</option><option value="user" ${S.src==="user"?"selected":""}>My saved case (Case manager)</option></select></label> ${S.src==="case"?`<label>Case <select data-k="sel">${caseOpts(S.sel)}</select></label>`:`<label>My case <select data-k="cid"><option value="">–</option>${uc.map(u=>`<option value="${u.id}" ${S.cid===u.id?"selected":""}>${esc(u.def.title)}</option>`).join("")}</select></label>`} <label>Person <select data-k="who"><option value="A" ${S.who==="A"?"selected":""}>Person A</option><option value="B" ${S.who==="B"?"selected":""}>Person B</option></select></label> <label>Aspect system <select data-k="asp"><option value="P1" ${S.asp==="P1"?"selected":""}>Rahu and Ketu without aspects</option><option value="P2" ${S.asp==="P2"?"selected":""}>Rahu and Ketu aspect 5, 7, 9</option></select></label></p>${S.src==="case"&&!unlocked("chart",S.sel)?gateBox("chart",S.sel):""}</div>`;
}
function chHandler(S,t){if(t.dataset.g){setGate(t);return true}const k=t.dataset.k;if(!k)return false;S[k]=t.value;return true}
const gk=S=>S.src==="case"?S.sel:S.cid;
W("p14charts","p14ch",CDEF,(S)=>{
  let h=caseChooser(S);const cs=chartSource(S);if(cs.locked||cs.none)return h+(cs.none?`<div class="note">Save a case in the Case manager first.</div>`:"");
  const p=S.who==="A"?cs.r.A:cs.r.B,ch=p.chart;if(!ch)return h+`<div class="note">Planet positions were not entered for this person.</div>`;
  h+=`<div class="card"><h3>${esc(p.label)}: D-1 (rashi) chart</h3><p class="tag">${esc(ch.positionsNote)} Whole-sign houses; aspect system: ${esc(ch.aspectSystem.name)}.</p>
  ${tbl(["Body","Longitude","Sign","Degree in sign","Nakshatra","Pada","House","Lordship","Retro","Dignity","Combust"],["Lagna"].concat(BODIES).map(k=>{if(k==="Lagna")return ["Lagna",dmsx(ch.lagna.L),ch.lagna.signName,dmsx(ch.lagna.degIn),"–","–",1,"–","–","–","–"];const b=ch.bodies[k];return [k+(b.schematic?" *":""),dmsx(b.L),b.signName,dmsx(b.degIn),esc(b.nakName),b.pada,b.house,b.lordOf.length?"houses "+b.lordOf.join(", "):"–",b.retro?"R":"–",esc(b.dignity.label),b.combust?"yes ("+PX().util.yrs(b.sunDistance)+"° from Sun)":"no"]}))}<p class="tag">* schematic teaching value; the Moon is calculated by the app's approximate engine.</p>${chartSvgs(ch,"d1")}</div>
  <div class="card"><h3>House table</h3>${tbl(["House","Sign","Lord","Occupants","Aspected by"],ch.houses.map(x=>[x.house,x.signName,x.lord,esc(x.occupants.join(", ")||"–"),esc(x.aspectedBy.join(", ")||"–")]))}<p class="tag">Conjunctions (same sign): ${esc(ch.houses.filter(x=>x.occupants.length>1).map(x=>x.signName+": "+x.occupants.join("+")).join("; ")||"none")}.</p></div>
  <div class="card"><h3>${esc(p.label)}: D-9 (Navamsha) derived from the D-1 longitudes</h3><p class="tag">Navamsha sign = floor(longitude / 3°20′) mod 12 (Aries = 0). D-9 Lagna: ${esc(ch.d9.lagnaName)} (lord ${esc(ch.d9.lagnaLord)}).</p>
  ${tbl(["Body","D-1 sign","D-9 sign","D-9 house","D-9 dignity","Vargottama"],BODIES.map(k=>[k,ch.bodies[k].signName,ch.d9.bodies[k].signName,ch.d9.bodies[k].house,esc(ch.d9.bodies[k].dignity.label),ch.bodies[k].vargottama?"yes":"–"]))}${chartSvgs(ch,"d9")}</div>
  <div class="card"><h3>Jaimini (optional): Chara Karakas, seven-planet scheme</h3>${tbl(["Planet","Degree in sign","Karaka"],ch.karakas.map(k=>[k.planet,dmsx(k.degIn),k.karaka]))}<p class="tag">Darakaraka: ${esc(ch.darakaraka)}. Rahu is not used in this scheme; other Jaimini schools differ. Upapada Lagna is taught in Day 13.</p></div>`;
  return h},(S,t)=>{if(t.dataset.k==="src"||t.dataset.k==="sel"||t.dataset.k==="cid"||t.dataset.k==="who"||t.dataset.k==="asp"||t.dataset.g)return chHandler(S,t);return false});
function layerBlock(title,o){if(!o||!o.available)return `<div class="card"><h4>${esc(title)}</h4><p>Not available (positions not entered).</p></div>`;
  return `<div class="card"><h4>${esc(title)}</h4>${tbl(["Topic","Observation","Polarity","Basis"],o.items.map(i=>[esc(i.topic||i.id),esc(i.text),i.polarity?`<span style="background:${i.polarity==="supportive"?COL.ok:i.polarity==="challenging"?COL.bad:COL.amb};padding:1px 6px;border-radius:4px">${i.polarity==="supportive"?"✓ ":i.polarity==="challenging"?"✗ ":"◐ "}${esc(i.polarity)}</span>`:"–",esc(i.basis||i.rule||"")]))}</div>`}
W("p14layers","p14ch",CDEF,(S)=>{
  let h=caseChooser(S);const cs=chartSource(S);if(cs.locked||cs.none)return h+(cs.none?`<div class="note">Save a case in the Case manager first.</div>`:"");
  const r=cs.r,P=PX();
  h+=`<div class="note"><b>Read this first.</b> Observations are rule-based reading aids (course teaching heuristic, grade E). “Supportive” and “challenging” describe possibilities that the practitioner must verify with the chosen school; they are not predictions and they are never added into a score. Each layer stays separate.</div>`;
  h+=layerBlock("Person A: individual observations (D-1)",r.layers.A)+layerBlock("Person A: Navamsha (D-9)",r.layers.d9A)+layerBlock("Person B: individual observations (D-1)",r.layers.B)+layerBlock("Person B: Navamsha (D-9)",r.layers.d9B)+layerBlock("Mutual chart comparison",r.layers.mutual);
  h+=`<div class="card"><h4>Layer summaries and suggested reporting category</h4>${tbl(["Layer","Summary"],Object.entries(r.synthesis.layerSummary).map(([k,v])=>[k,esc(v)]))}<p><b>Suggested category:</b> ${esc(r.synthesis.suggestedCategory)}</p><p class="tag">${esc(r.synthesis.categoryBasis)} There is no combined score.</p></div>`;
  return h},(S,t)=>{if(t.dataset.k==="src"||t.dataset.k==="sel"||t.dataset.k==="cid"||t.dataset.k==="who"||t.dataset.k==="asp"||t.dataset.g)return chHandler(S,t);return false});
W("p14dasha","p14ch",CDEF,(S)=>{
  let h=caseChooser(S);const cs=chartSource(S);if(cs.locked||cs.none)return h+(cs.none?`<div class="note">Save a case in the Case manager first.</div>`:"");
  const r=cs.r,P=PX(),t=S.who==="A"?r.timing.A:r.timing.B,d=t.dasha,iso=P.util.iso,yrs=P.util.yrs,cur=t.current;
  h+=`<div class="card"><p><label>Year length <select data-k="yd"><option value="365.25" ${Number(S.yd)===365.25?"selected":""}>365.25 days</option><option value="360" ${Number(S.yd)===360?"selected":""}>360 days</option></select></label> · Analysis date: ${esc(r.timing.analysisDate)}</p>
  <h3>Vimshottari at birth: ${esc(S.who==="A"?"Person A":"Person B")}</h3><p>Moon Nakshatra lord (first Mahadasha): <b>${esc(d.lord)}</b>. Fraction of the Nakshatra elapsed: ${yrs(d.fractionElapsed)}. Elapsed ${yrs(d.elapsedYears)} years; <b>balance ${yrs(d.balanceYears)} years</b>.</p>
  ${tbl(["Mahadasha","Years","Start (UT date)","End (UT date)","Marriage-relevance flags (checklist, not a prediction)"],d.mahadashas.map(m=>[esc(m.lord)+(m.first?" (balance at birth)":""),m.years,iso(m.startMs),iso(m.endMs),esc(P.Timing.dashaFlags(m.lord,(S.who==="A"?r.A:r.B).chart).join("; ")||"–")]))}
  ${cur?`<h4>At the analysis date</h4><p>Mahadasha <b>${esc(cur.md.lord)}</b> (${cur.md.start} to ${cur.md.end}); Antardasha <b>${esc(cur.ad.lord)}</b> (${cur.ad.start} to ${cur.ad.end}); Pratyantardasha <b>${esc(cur.pd?cur.pd.lord:"–")}</b>${cur.pd?` (${cur.pd.start} to ${cur.pd.end})`:""}.</p>`:"<p>The analysis date is outside the 120-year table.</p>"}
  <h4>Antardashas of the Mahadasha current at the analysis date</h4>${cur?tbl(["Antardasha","Years","Start","End"],P.Timing.subPeriods(d.mahadashas.find(m=>m.lord===cur.md.lord),d.yearDays).map(a=>[esc(a.lord),yrs(a.years),iso(a.startMs),iso(a.endMs)])):""}
  <p class="tag">${esc(t.note)} The two people's periods are compared as a timing observation only; they never change a Koota result.</p></div>`;
  return h},(S,t)=>{if(t.dataset.k==="yd"){S.yd=t.value;return true}return chHandler(S,t)});
/* ---------- 11. case manager ---------- */
const CMDEF={list:[],sel:"",cloneOk:false};
function newCaseRecord(def,title){const P=PX();return {id:def.id,def,status:"Draft",tradition:"TRADITION_A_ASHTAKOOTA_RAJJU_VEDHA",notes:"",history:[{t:new Date().toISOString().slice(0,16),from:"",to:"Draft",note:title||"created"}]}}
const TRAD=[["TRADITION_A_ASHTAKOOTA_RAJJU_VEDHA","Tradition A (Ashtakoota + Rajju + Vedha)"],["NORTH_INDIAN_ASHTAKOOTA_BASE","North Indian Ashtakoota base (eight Kootas)"],["TAMIL_PATHU_PORUTHAM_PROFILE_A","Tamil Pathu Porutham, provisional profile"],["TELUGU_DASHAKOOTA_PROFILE_A","Telugu Dasha Koota (pending research)"],["KANNADA_DASHAKOOTA_PROFILE_A","Kannada Dasha Koota (pending research)"],["KERALA_ANUKULYA_PROFILE_A","Kerala Anukulya (pending research)"]];
function personForm(def,w){const p=def[w],b=p.birth,k=(f)=>`data-k="f" data-w="${w}" data-f="${f}"`;
  return `<div class="card"><h4>${esc(p.label)} (${p.role} role)</h4><div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:6px">
  <label>Date<input type="date" value="${esc(b.date)}" ${k("date")}></label><label>Time (HH:MM:SS)<input value="${esc(b.time)}" ${k("time")}></label><label>Place<input value="${esc(b.place)}" ${k("place")}></label><label>Country<input value="${esc(b.country)}" ${k("country")}></label>
  <label>Latitude<input type="number" step="0.0001" value="${b.lat}" ${k("lat")}></label><label>Longitude<input type="number" step="0.0001" value="${b.lon}" ${k("lon")}></label><label>Standard offset (h)<input type="number" step="0.25" value="${b.stdOffset}" ${k("stdOffset")}></label><label>Daylight saving (h)<input type="number" step="0.5" value="${b.dst}" ${k("dst")}></label>
  <label>Time accuracy<select ${k("accuracy")}>${PX().constants.ACCURACY.map(a=>`<option ${b.accuracy===a.label?"selected":""}>${esc(a.label)}</option>`).join("")}</select></label></div>
  <details><summary>Enter Lagna and planet positions (sidereal; optional, from your own ephemeris)</summary><p class="tag">Without positions only the Moon-based layers are available. Rahu is the mean node; Ketu is set opposite.</p><div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(170px,1fr));gap:6px">${["Lagna","Sun","Mars","Mercury","Jupiter","Venus","Saturn","Rahu"].map(n=>{const v=p.sch?p.sch[n]:null,s=v===null?"":Math.floor(v/30),d=v===null?"":(v%30).toFixed(2);return `<label>${n}<select ${k("sign_"+n)}><option value="">–</option>${SIGNS.map((x,i)=>`<option value="${i}" ${s===i?"selected":""}>${x}</option>`).join("")}</select><input type="number" step="0.01" min="0" max="29.99" value="${d}" placeholder="degrees" ${k("deg_"+n)}></label>`}).join("")}</div></details></div>`}
function setField(def,w,f,v){const p=def[w];
  if(f.startsWith("sign_")||f.startsWith("deg_")){const n=f.split("_")[1];p.sch=p.sch||{retro:[]};const cur=p.sch[n];let s=cur===undefined?"":Math.floor(cur/30),d=cur===undefined?0:cur%30;if(f.startsWith("sign_"))s=v===""?"":Number(v);else d=Number(v)||0;if(s==="")delete p.sch[n];else p.sch[n]=s*30+d;
    if(!["Lagna","Sun","Mars","Mercury","Jupiter","Venus","Saturn","Rahu"].every(x=>p.sch[x]!==undefined))p.sch._incomplete=true;else delete p.sch._incomplete;return}
  const num=["lat","lon","stdOffset","dst"];p.birth[f]=num.includes(f)?Number(v):v}
W("p14cases","p14cases",CMDEF,(S)=>{
  const P=PX(),sel=S.list.find(x=>x.id===S.sel);
  let h=`<div class="card"><h3>Case manager (stored on this device only)</h3><p>${S.list.length} saved case(s). Statuses: ${P.Workflow.statuses.map(esc).join(" → ")}.</p><p><button data-a="new">New blank case</button> <label>Copy a teaching case <select data-k="clonesel">${caseOpts(S.clonesel||"C01")}</select></label> <button data-a="clone" ${S.cloneOk?"":"disabled"}>Copy inputs</button><br><label><input type="checkbox" data-k="cloneok" ${S.cloneOk?"checked":""}> I have finished my own working for the case I copy (a copy shows the engine's Moon and Koota results)</label></p>
  <p>${S.list.length?`<label>Open <select data-k="sel"><option value="">–</option>${S.list.map(x=>`<option value="${x.id}" ${S.sel===x.id?"selected":""}>${esc(x.def.title)} (${esc(x.status)})</option>`).join("")}</select></label>`:"<span class='tag'>No saved case yet.</span>"}</p></div>`;
  if(!sel)return h;
  const def=sel.def,st=P.Workflow.statuses,i=st.indexOf(sel.status);
  h+=`<div class="card"><h3>${esc(def.title)} <span class="tag">${esc(sel.id)}</span></h3><p><label>Title <input data-k="title" value="${esc(def.title)}" style="width:60%"></label></p>
  <p><b>Status: ${esc(sel.status)}</b> ${i<st.length-2?`<button data-a="adv">Advance to “${esc(st[i+1])}”</button>`:""} ${i>0&&sel.status!=="Archived"?`<button data-a="back">Return one stage</button>`:""} ${sel.status!=="Archived"?`<button data-a="arch">Archive</button>`:""}</p><div id="p14cmsg"></div>
  <p><label>Matching tradition <select data-k="trad">${TRAD.map(t=>`<option value="${t[0]}" ${sel.tradition===t[0]?"selected":""}>${esc(t[1])}</option>`).join("")}</select></label></p>
  <p><label>Analysis date (Dasha) <input type="date" data-k="adate" value="${esc(def.analysisDate)}"></label></p></div>`;
  h+=personForm(def,"A")+personForm(def,"B");
  h+=`<div class="card"><label>Practitioner notes (kept separate from automatic output)<br><textarea data-k="notes" rows="3" style="width:100%">${esc(sel.notes)}</textarea></label></div>`;
  // validation and quick results
  let calc="";
  try{const incomplete=["A","B"].some(w=>def[w].sch&&def[w].sch._incomplete);const d2=JSON.parse(JSON.stringify(def));["A","B"].forEach(w=>{if(d2[w].sch&&d2[w].sch._incomplete)d2[w].sch=null;if(d2[w].sch)d2[w].sch.retro=d2[w].sch.retro||[]});
    const r=P.Case.compute(d2);
    calc=`<div class="card"><h3>Validation and Moon results</h3>${["A","B"].map(w=>{const v=P.Case.validateBirth(def[w].birth),p=r[w];return `<p><b>${esc(def[w].label)}:</b> ${v.warnings.map(x=>"⚠ "+esc(x)).join("<br>")||"no warnings"}<br>Moon ${dmsx(p.moon.L)} sidereal: ${esc(p.moon.rashiName)} / ${esc(p.moon.nakName)} Pada ${p.moon.pada} (Nakshatra lord ${esc(p.moon.nakLord)}). ${esc(p.sensitivity.note)} Second-ayanamsha check (${esc(p.crossCheck.ayanamsha)}): ${p.crossCheck.same?"same Rashi, Nakshatra and Pada":"differs: "+esc(p.crossCheck.rashiName+" / "+p.crossCheck.nakName+" Pada "+p.crossCheck.pada)}.</p>`}).join("")}
      <p><b>Scored total (Tradition A):</b> ${r.sheet.total} of 36; recognised Doshas: ${esc(r.sheet.register.filter(d=>d.type.startsWith("Recognised")).map(d=>d.koota).join(", ")||"none")}. ${incomplete?"<span class='tag'>Planet positions are incomplete; chart layers are unavailable.</span>":""}</p><p class="tag">Open the other panels and choose “My saved case” to see charts, layers, Dasha and the report.</p></div>`}
  catch(e){calc=`<div class="note" style="border-color:var(--bad)"><b>Cannot calculate yet:</b> ${esc(e.message)}</div>`}
  h+=calc;
  h+=`<div class="card"><h4>History</h4><ul>${sel.history.map(x=>`<li>${esc(x.t)} ${esc(x.from?x.from+" → ":"")}${esc(x.to)} ${esc(x.note||"")}</li>`).join("")}</ul><p><button data-a="export">Download the case record (JSON)</button> <button data-a="del">Delete this case</button></p></div>`;
  return h},
 (S,t)=>{const P=PX(),sel=S.list.find(x=>x.id===S.sel);
  const msg=m=>{const el=document.getElementById("p14cmsg");if(el)el.innerHTML=`<div class="note" style="border-color:var(--bad)">${esc(m)}</div>`};
  const log=(from,to,note)=>sel.history.push({t:new Date().toISOString().slice(0,16),from,to,note:note||""});
  if(t.dataset.a==="new"){const def=P.customCase();const rec=newCaseRecord(def,"new blank case");S.list=S.list.concat([rec]);S.sel=rec.id;return true}
  if(t.dataset.k==="cloneok"){S.cloneOk=t.checked;return true}
  if(t.dataset.k==="clonesel"){S.clonesel=t.value;return true}
  if(t.dataset.a==="clone"){if(!S.cloneOk)return false;const c=P.Case.get(S.clonesel||"C01"),def=JSON.parse(JSON.stringify(c));def.id="U"+Date.now().toString(36).toUpperCase();def.title="Copy of "+c.title;delete def.expect;delete def.exam;const rec=newCaseRecord(def,"copied inputs from "+c.id);S.list=S.list.concat([rec]);S.sel=rec.id;return true}
  if(t.dataset.k==="sel"){S.sel=t.value;return true}
  if(!sel)return false;
  if(t.dataset.k==="title"){sel.def.title=t.value;return true}
  if(t.dataset.k==="trad"){sel.tradition=t.value;return true}
  if(t.dataset.k==="adate"){sel.def.analysisDate=t.value;return true}
  if(t.dataset.k==="notes"){sel.notes=t.value;return true}
  if(t.dataset.k==="f"){setField(sel.def,t.dataset.w,t.dataset.f,t.value);return true}
  if(t.dataset.a==="adv"||t.dataset.a==="back"||t.dataset.a==="arch"){const st=P.Workflow.statuses,i=st.indexOf(sel.status),to=t.dataset.a==="adv"?st[i+1]:t.dataset.a==="arch"?"Archived":st[i-1];
    try{const r=P.Workflow.transition(sel.status,to);
      if(to==="Calculation Verified"||to==="Koota Analysis Complete"){const v=["A","B"].map(w=>P.Case.validateBirth(sel.def[w].birth));if(v.some(x=>!x.ok)){msg("Cannot move to "+to+": the birth data has errors: "+v.flatMap(x=>x.errors).join(" "));return false}}
      log(sel.status,to,r.note);sel.status=to}catch(e){msg(e.message);return false}return true}
  if(t.dataset.a==="del"){S.list=S.list.filter(x=>x.id!==sel.id);S.sel="";return true}
  if(t.dataset.a==="export"){down(sel.id+"_case_record.json",JSON.stringify(sel,null,2),"application/json");return false}
  return false});
/* ---------- 12. report builder ---------- */
const RDEF={src:"case",sel:"C01",cid:"",asp:"P1",yd:365.25,who:"A",nameA:"Person A",nameB:"Person B",prac:"",notes:"",version:1,show:false};
W("p14report","p14rep",RDEF,(S)=>{
  const P=PX();let h=`<div class="card"><h3>Professional report builder</h3><p><label>Source <select data-k="src"><option value="case" ${S.src==="case"?"selected":""}>Teaching case</option><option value="user" ${S.src==="user"?"selected":""}>My saved case</option></select></label> ${S.src==="case"?`<label>Case <select data-k="sel">${caseOpts(S.sel)}</select></label>`:`<label>My case <select data-k="cid"><option value="">–</option>${userCases().map(u=>`<option value="${u.id}" ${S.cid===u.id?"selected":""}>${esc(u.def.title)}</option>`).join("")}</select></label>`}</p>
  <p><label>Identifier A <input data-k="nameA" value="${esc(S.nameA)}"></label> <label>Identifier B <input data-k="nameB" value="${esc(S.nameB)}"></label> <label>Practitioner <input data-k="prac" value="${esc(S.prac)}"></label> <label>Version <input type="number" min="1" data-k="version" value="${S.version}" style="width:60px"></label></p>
  <p><label>Practitioner notes (kept separate)<br><textarea data-k="notes" rows="3" style="width:100%">${esc(S.notes)}</textarea></label></p>${S.src==="case"&&!unlocked("rep",S.sel)?gateBox("rep",S.sel,"Prepare your own report first; the generator then shows the engine's version for comparison."):""}</div>`;
  const key=S.src==="case"?S.sel:S.cid;if(S.src==="case"&&!unlocked("rep",S.sel))return h;
  let r;try{if(S.src==="case")r=P.Case.compute(S.sel,{aspect:S.asp});else{const u=userCases().find(x=>x.id===S.cid);if(!u)return h+`<div class="note">Save a case in the Case manager first.</div>`;const d2=JSON.parse(JSON.stringify(u.def));["A","B"].forEach(w=>{if(d2[w].sch&&d2[w].sch._incomplete)d2[w].sch=null});r=P.Case.compute(d2)}}catch(e){return h+`<div class="note" style="border-color:var(--bad)"><b>Cannot build:</b> ${esc(e.message)}</div>`}
  const rep=P.Report.build(r,{nameA:S.nameA,nameB:S.nameB,practitioner:{name:S.prac||"Practitioner (to be completed)",notes:S.notes},version:Number(S.version)||1,approval:"Report Draft"});
  h+=`<div class="card"><p><button data-a="print">Print</button> <button data-a="json">Download JSON</button> <button data-a="short">Show the short executive summary</button> <button data-a="full">Show the full report</button></p><div id="p14repout" style="max-height:70vh;overflow:auto">${S.show==="short"?execSummary(rep):P.Report.html(rep)}</div></div>`;
  return h},
 (S,t,e,el)=>{const P=PX();
  if(t.dataset.g){setGate(t);return true}
  if(t.dataset.k){const k=t.dataset.k;S[k]=k==="version"?Number(t.value):t.value;return true}
  const out=el.querySelector("#p14repout");
  if(t.dataset.a==="short"){S.show="short";return true}if(t.dataset.a==="full"){S.show="full";return true}
  if(t.dataset.a==="print"&&out){printHtml("ASTROSUTRAS report",out.innerHTML);return false}
  if(t.dataset.a==="json"){try{let r;if(S.src==="case")r=P.Case.compute(S.sel);else{const u=userCases().find(x=>x.id===S.cid);r=P.Case.compute(u.def)}down("astrosutras_report.json",JSON.stringify(P.Report.build(r,{nameA:S.nameA,nameB:S.nameB,practitioner:{name:S.prac,notes:S.notes},version:Number(S.version)||1}),null,2),"application/json")}catch(x){}return false}
  return false});
