  if(!v.ok)return h+`<div class="note" style="border-color:var(--bad)"><b>Errors</b><ul>${v.errors.map(e=>`<li>${esc(e)}</li>`).join("")}</ul></div></div>`;
  let m;try{m=P.Case.personOf({label:"Person",role:"bride",birth:b,sch:null},{ayanamsha:S.ay})}catch(e){return h+`<div class="note" style="border-color:var(--bad)">${esc(e.message)}</div></div>`}
  h+=v.warnings.length?`<div class="note"><b>Warnings</b><ul>${v.warnings.map(e=>`<li>${esc(e)}</li>`).join("")}</ul></div>`:`<p>${ok("✓ no warnings")}</p>`;
