function prereq(){const p=T().prereq;return `<h1>${esc(p.title)}</h1><h2>${esc(p.ess)}</h2><ul>${(p.essL||[]).map(i=>`<li>${esc(i)}</li>`).join("")}</ul><h2>${esc(p.rec)}</h2><ul>${(p.recL||[]).map(i=>`<li>${esc(i)}</li>`).join("")}</ul>`}
